/* ===== CSS VARIABLES ===== */
:root {
  --color-bg:        #e4e4e0;
  --color-surface:   #dcdcd6;
  --color-accent:    #e8192a;
  --color-accent-dim:#b81422;
  --color-text:      #1a1a18;
  --color-text-soft: #5c5c55;
  --color-border:    #c4c4bd;
  --color-border-subtle: #d2d2cb;
  --color-white:     #fafaf7;

  --font-sans:   'Inter', 'SF Pro Display', 'Segoe UI', system-ui, -apple-system, sans-serif;
  --font-mono:   'JetBrains Mono', 'SF Mono', 'Fira Code', 'Cascadia Code', 'Consolas', monospace;

  --space-xs:  0.5rem;
  --space-sm:  0.75rem;
  --space-md:  1rem;
  --space-lg:  1.5rem;
  --space-xl:  2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;

  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;

  --max-width: 1100px;
}

/* ===== RESET ===== */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

img,
svg {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

ul {
  list-style: none;
}

/* ===== UTILITY ===== */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin-inline: auto;
  padding-inline: var(--space-lg);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ===== TYPOGRAPHY ===== */
h1, h2, h3, h4 {
  letter-spacing: 0.06em;
  font-weight: 600;
  line-height: 1.2;
}

.section-heading {
  text-align: center;
  font-size: clamp(1.5rem, 4vw, 2.2rem);
  letter-spacing: 0.08em;
  margin-bottom: var(--space-2xl);
  color: var(--color-text);
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-xs);
  padding: 0.7rem 1.6rem;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  border-radius: var(--radius-sm);
  border: 1.5px solid transparent;
  cursor: pointer;
  transition: background-color 0.2s, border-color 0.2s, color 0.2s;
  font-family: inherit;
}

.btn--primary {
  background-color: var(--color-accent);
  color: var(--color-white);
  border-color: var(--color-accent);
}

.btn--primary:hover {
  background-color: var(--color-accent-dim);
  border-color: var(--color-accent-dim);
}

.btn--ghost {
  background-color: transparent;
  color: var(--color-text);
  border-color: var(--color-border);
}

.btn--ghost:hover {
  border-color: var(--color-text);
  background-color: rgba(0,0,0,0.03);
}

/* ===== NAVIGATION ===== */
.nav {
  padding-block: var(--space-md);
  border-bottom: 1px solid var(--color-border-subtle);
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: rgba(228, 228, 224, 0.85);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-lg);
}

.nav__logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-weight: 700;
  font-size: 1.15rem;
  letter-spacing: 0.08em;
  color: var(--color-text);
}

.nav__logo svg {
  color: var(--color-accent);
}

.nav__links {
  display: flex;
  gap: var(--space-xl);
  font-size: 0.9rem;
  font-weight: 500;
  letter-spacing: 0.04em;
}

.nav__links a {
  color: var(--color-text-soft);
  transition: color 0.2s;
  padding-block: 0.25rem;
  border-bottom: 1.5px solid transparent;
}

.nav__links a:hover {
  color: var(--color-accent);
  border-bottom-color: var(--color-accent);
}

/* ===== HERO ===== */
.hero {
  padding-block: var(--space-3xl) var(--space-2xl);
  text-align: center;
}

.hero__inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-lg);
}

.hero__badge {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-accent);
  border: 1px solid var(--color-accent);
  border-radius: 999px;
  padding: 0.3rem 1rem;
}

.hero__headline {
  font-size: clamp(1.8rem, 6vw, 3.2rem);
  letter-spacing: 0.07em;
  max-width: 800px;
  line-height: 1.15;
}

.hero__highlight {
  color: var(--color-accent);
  position: relative;
}

.hero__subhead {
  font-size: 1.05rem;
  color: var(--color-text-soft);
  max-width: 640px;
  line-height: 1.7;
}

.hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-md);
  justify-content: center;
  margin-top: var(--space-sm);
}

/* ===== METRICS STRIP ===== */
.metrics {
  padding-block: var(--space-2xl);
  border-top: 1px solid var(--color-border-subtle);
  border-bottom: 1px solid var(--color-border-subtle);
  background-color: var(--color-surface);
}

.metrics__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.metric-card {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-xs);
}

.metric-card__label {
  font-family: var(--font-mono);
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  color: var(--color-accent);
  text-transform: lowercase;
}

.metric-card__value {
  font-family: var(--font-mono);
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--color-text);
  line-height: 1;
}

.metric-card__unit {
  font-size: 0.6em;
  font-weight: 500;
  color: var(--color-text-soft);
}

.metric-card__desc {
  font-size: 0.85rem;
  color: var(--color-text-soft);
  max-width: 220px;
  line-height: 1.5;
}

/* ===== FEATURES ===== */
.features {
  padding-block: var(--space-3xl);
}

.features__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.feature-card {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-xl);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
  background-color: var(--color-white);
  transition: border-color 0.25s, box-shadow 0.25s;
}

.feature-card:hover {
  border-color: var(--color-accent);
  box-shadow: 0 4px 20px rgba(232, 25, 42, 0.07);
}

.feature-card__icon {
  color: var(--color-accent);
  margin-bottom: var(--space-xs);
}

.feature-card__title {
  font-size: 1.15rem;
  letter-spacing: 0.06em;
  font-weight: 650;
}

.feature-card__body {
  font-size: 0.92rem;
  color: var(--color-text-soft);
  line-height: 1.65;
  flex-grow: 1;
}

.feature-card__body em {
  font-style: italic;
  color: var(--color-text);
}

/* ===== TESTIMONIAL ===== */
.testimonial {
  padding-block: var(--space-3xl);
  border-top: 1px solid var(--color-border-subtle);
  background-color: var(--color-surface);
}

.testimonial__quote {
  max-width: 720px;
  margin-inline: auto;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}

.testimonial__quote blockquote {
  font-size: clamp(1.05rem, 2.5vw, 1.3rem);
  font-style: italic;
  line-height: 1.7;
  color: var(--color-text);
  position: relative;
  padding: 0;
  quotes: "\201C" "\201D" "\2018" "\2019";
}

.testimonial__quote blockquote::before {
  content: open-quote;
  font-size: 4rem;
  line-height: 0;
  color: var(--color-accent);
  font-style: normal;
  vertical-align: -0.5em;
  margin-right: 0.1em;
  font-family: Georgia, serif;
}

.testimonial__quote blockquote::after {
  content: close-quote;
  font-size: 4rem;
  line-height: 0;
  color: var(--color-accent);
  font-style: normal;
  vertical-align: -0.6em;
  margin-left: 0.05em;
  font-family: Georgia, serif;
}

.testimonial__quote figcaption {
  font-size: 0.9rem;
  color: var(--color-text-soft);
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  letter-spacing: 0.03em;
}

.testimonial__quote figcaption strong {
  color: var(--color-text);
  font-weight: 650;
}

/* ===== FOOTER ===== */
.footer {
  padding-block: var(--space-2xl);
  border-top: 1px solid var(--color-border);
  margin-top: auto;
}

.footer__inner {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: flex-start;
  gap: var(--space-xl);
}

.footer__brand {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
}

.footer__logo {
  font-weight: 700;
  font-size: 1.1rem;
  letter-spacing: 0.08em;
  color: var(--color-accent);
}

.footer__tagline {
  font-size: 0.85rem;
  color: var(--color-text-soft);
}

.footer__social {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.footer__social-label {
  font-weight: 650;
  font-size: 0.85rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-text-soft);
}

.footer__social-list {
  display: flex;
  gap: var(--space-lg);
  font-size: 0.9rem;
}

.footer__social-list a {
  color: var(--color-text-soft);
  border-bottom: 1px solid transparent;
  padding-bottom: 2px;
  transition: color 0.2s, border-color 0.2s;
}

.footer__social-list a:hover {
  color: var(--color-accent);
  border-bottom-color: var(--color-accent);
}

.footer__copy {
  width: 100%;
  font-size: 0.78rem;
  color: var(--color-text-soft);
  text-align: center;
  margin-top: var(--space-md);
  padding-top: var(--space-md);
  border-top: 1px solid var(--color-border-subtle);
}

/* ===== RESPONSIVE ===== */

/* Tablet — two columns for features, keep metrics 3-across */
@media (max-width: 900px) {
  .features__grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .metrics__grid {
    gap: var(--space-lg);
  }

  .nav__links {
    gap: var(--space-lg);
  }
}

/* Small tablet / large phone */
@media (max-width: 640px) {
  :root {
    --space-2xl: 2rem;
    --space-3xl: 2.5rem;
  }

  .features__grid {
    grid-template-columns: 1fr;
    max-width: 440px;
    margin-inline: auto;
  }

  .metrics__grid {
    grid-template-columns: 1fr 1fr 1fr;
    gap: var(--space-md);
  }

  .metric-card__desc {
    font-size: 0.75rem;
  }

  .hero__headline {
    letter-spacing: 0.04em;
  }

  .hero__subhead {
    font-size: 0.95rem;
  }

  .nav__links {
    gap: var(--space-md);
    font-size: 0.8rem;
  }

  .footer__inner {
    flex-direction: column;
    align-items: center;
    text-align: center;
  }

  .testimonial__quote blockquote {
    font-size: 1rem;
  }
}

/* Phone — single column everywhere except tiny metrics */
@media (max-width: 480px) {
  .container {
    padding-inline: var(--space-md);
  }

  .metrics__grid {
    grid-template-columns: 1fr;
    gap: var(--space-lg);
  }

  .metric-card__desc {
    max-width: 100%;
  }

  .hero__actions {
    flex-direction: column;
    width: 100%;
    max-width: 300px;
  }

  .hero__actions .btn {
    width: 100%;
  }

  .nav__links {
    gap: var(--space-sm);
    font-size: 0.75rem;
  }

  .nav__logo span {
    font-size: 0.95rem;
  }

  .feature-card {
    padding: var(--space-lg);
  }

  .section-heading {
    margin-bottom: var(--space-xl);
  }
}

/* Extra small — 320px minimum */
@media (max-width: 380px) {
  .nav__links {
    gap: 0.5rem;
    font-size: 0.7rem;
  }

  .nav__logo span {
    display: none;
  }

  .hero__badge {
    font-size: 0.7rem;
    padding: 0.25rem 0.7rem;
  }

  .hero__headline {
    font-size: clamp(1.4rem, 6vw, 1.8rem);
  }
}

args.content:
/* ============================================================
   Murmur — Tech-Noir Design System
   CSS Variables | Thin Borders | Wide Letter-Spacing | #e8192a
   ============================================================ */

:root {
  /* ---- Palette ---- */
  --color-bg:         #e4e4e0;
  --color-surface:    #dadad4;
  --color-border:     #b8b8af;
  --color-text:       #1a1a1a;
  --color-text-muted: #5c5c55;
  --color-accent:     #e8192a;
  --color-accent-dim: #c4121f;
  --color-white:      #fafaf7;

  /* ---- Typography ---- */
  --font-sans:   'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --font-mono:   'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace;
  --ls-heading:  0.06em;
  --ls-display:  0.08em;

  /* ---- Spacing ---- */
  --space-xs:  0.25rem;
  --space-sm:  0.5rem;
  --space-md:  1rem;
  --space-lg:  2rem;
  --space-xl:  4rem;
  --space-2xl: 6rem;

  /* ---- Layout ---- */
  --max-width:   1100px;
  --radius:      3px;
  --border-thin: 1px solid var(--color-border);
}

/* ============================================================
   RESET & BASE
   ============================================================ */

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 100%;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-height: 100vh;
}

img, svg {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

/* Screen-reader-only utility */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* ============================================================
   HEADER
   ============================================================ */

.site-header {
  border-bottom: var(--border-thin);
  background-color: var(--color-bg);
  position: sticky;
  top: 0;
  z-index: 10;
  backdrop-filter: blur(8px);
}

.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  font-family: var(--font-mono);
  font-size: 1.25rem;
  font-weight: 600;
  letter-spacing: var(--ls-display);
  text-transform: lowercase;
  color: var(--color-accent);
  transition: opacity 0.2s;
}

.logo:hover {
  opacity: 0.75;
}

.nav-links {
  display: flex;
  gap: var(--space-lg);
}

.nav-links a {
  font-size: 0.9rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--color-text-muted);
  border-bottom: 2px solid transparent;
  padding-bottom: 4px;
  transition: color 0.2s, border-color 0.2s;
}

.nav-links a:hover {
  color: var(--color-text);
  border-bottom-color: var(--color-accent);
}

/* ============================================================
   HERO
   ============================================================ */

.hero {
  position: relative;
  padding: var(--space-2xl) 0 var(--space-xl);
  text-align: center;
  overflow: hidden;
}

.hero-accent-line {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 3px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    var(--color-accent) 20%,
    var(--color-accent) 80%,
    transparent 100%
  );
  opacity: 0.55;
}

.hero-badge {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  border: var(--border-thin);
  padding: 0.3em 1em;
  margin-bottom: var(--space-lg);
  background: var(--color-surface);
}

#hero-heading {
  font-family: var(--font-sans);
  font-size: clamp(2.2rem, 6vw, 4rem);
  font-weight: 700;
  letter-spacing: var(--ls-heading);
  line-height: 1.15;
  max-width: 18ch;
  margin: 0 auto var(--space-md);
  color: var(--color-text);
}

.hero-subtitle {
  font-size: 1.1rem;
  max-width: 52ch;
  margin: 0 auto var(--space-xl);
  color: var(--color-text-muted);
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-md);
  justify-content: center;
}

/* ---- Buttons ---- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75em 1.8em;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  border: var(--border-thin);
  background: transparent;
  color: var(--color-text);
  cursor: pointer;
  transition: background 0.2s, color 0.2s, border-color 0.2s;
  text-decoration: none;
}

.btn-primary {
  background-color: var(--color-accent);
  color: var(--color-white);
  border-color: var(--color-accent);
}

.btn-primary:hover {
  background-color: var(--color-accent-dim);
  border-color: var(--color-accent-dim);
}

.btn-ghost {
  border-color: var(--color-border);
  color: var(--color-text);
}

.btn-ghost:hover {
  background-color: var(--color-surface);
  border-color: var(--color-accent);
}

/* ============================================================
   METRICS STRIP  (id="metrics")
   ============================================================ */

.metrics-strip {
  padding: var(--space-xl) 0;
  border-top: var(--border-thin);
  border-bottom: var(--border-thin);
  background-color: var(--color-surface);
}

.metrics-strip .container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.metric-card {
  text-align: center;
  padding: var(--space-md);
}

.metric-label {
  display: block;
  font-family: var(--font-mono);
  font-size: 0.8rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: var(--space-xs);
}

.metric-value {
  display: block;
  font-family: var(--font-mono);
  font-size: clamp(2.5rem, 5vw, 3.5rem);
  font-weight: 700;
  letter-spacing: var(--ls-display);
  line-height: 1.1;
  color: var(--color-text);
  margin-bottom: var(--space-sm);
}

.metric-unit {
  font-size: 0.6em;
  font-weight: 500;
  color: var(--color-text-muted);
}

.metric-desc {
  font-size: 0.9rem;
  color: var(--color-text-muted);
  line-height: 1.55;
  max-width: 28ch;
  margin: 0 auto;
}

/* ============================================================
   FEATURES SECTION
   ============================================================ */

.features-section {
  padding: var(--space-2xl) 0;
}

.section-heading {
  text-align: center;
  font-family: var(--font-sans);
  font-size: clamp(1.6rem, 4vw, 2.2rem);
  font-weight: 700;
  letter-spacing: var(--ls-heading);
  margin-bottom: var(--space-xl);
  color: var(--color-text);
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.feature-card {
  background: var(--color-surface);
  border: var(--border-thin);
  padding: var(--space-xl) var(--space-lg);
  transition: border-color 0.2s, transform 0.2s;
}

.feature-card:hover {
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.feature-icon {
  color: var(--color-accent);
  margin-bottom: var(--space-md);
}

.feature-card h3 {
  font-family: var(--font-sans);
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  margin-bottom: var(--space-sm);
  color: var(--color-text);
}

.feature-card p {
  font-size: 0.95rem;
  color: var(--color-text-muted);
  line-height: 1.65;
}

/* ============================================================
   TESTIMONIAL
   ============================================================ */

.testimonial-section {
  padding: var(--space-2xl) 0;
  background-color: var(--color-surface);
  border-top: var(--border-thin);
  border-bottom: var(--border-thin);
}

.testimonial-quote {
  max-width: 640px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote p {
  font-size: 1.25rem;
  font-style: italic;
  line-height: 1.7;
  color: var(--color-text);
  margin-bottom: var(--space-lg);
  position: relative;
}

/* Decorative opening quote mark */
.testimonial-quote p::before {
  content: "“";
  display: block;
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 4rem;
  line-height: 1;
  color: var(--color-accent);
