/* ============================================================
   Murmur — Tech-Noir Design System
   CSS Variables | Thin Borders | Wide Letter-Spacing | #e8192a
   ============================================================ */

:root {
  /* ---- Palette ---- */
  --color-bg:         #e4e4e0;
  --color-surface:    #dadad4;
  --color-border:     #b8b8af;
  --color-text:       #1a1a1a;
  --color-text-muted: #5c5c55;
  --color-accent:     #e8192a;
  --color-accent-dim: #c4121f;
  --color-white:      #fafaf7;

  /* ---- Typography ---- */
  --font-sans:   'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --font-mono:   'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace;
  --ls-heading:  0.06em;
  --ls-display:  0.08em;

  /* ---- Spacing ---- */
  --space-xs:  0.25rem;
  --space-sm:  0.5rem;
  --space-md:  1rem;
  --space-lg:  2rem;
  --space-xl:  4rem;
  --space-2xl: 6rem;

  /* ---- Layout ---- */
  --max-width:   1100px;
  --radius:      3px;
  --border-thin: 1px solid var(--color-border);
}

/* ============================================================
   RESET & BASE
   ============================================================ */

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 100%;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-height: 100vh;
}

img, svg {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

/* Screen-reader-only utility */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* ============================================================
   HEADER
   ============================================================ */

.site-header {
  border-bottom: var(--border-thin);
  background-color: var(--color-bg);
  position: sticky;
  top: 0;
  z-index: 10;
  backdrop-filter: blur(8px);
}

.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  font-family: var(--font-mono);
  font-size: 1.25rem;
  font-weight: 600;
  letter-spacing: var(--ls-display);
  text-transform: lowercase;
  color: var(--color-accent);
  transition: opacity 0.2s;
}

.logo:hover {
  opacity: 0.75;
}

.nav-links {
  display: flex;
  gap: var(--space-lg);
}

.nav-links a {
  font-size: 0.9rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--color-text-muted);
  border-bottom: 2px solid transparent;
  padding-bottom: 4px;
  transition: color 0.2s, border-color 0.2s;
}

.nav-links a:hover {
  color: var(--color-text);
  border-bottom-color: var(--color-accent);
}

/* ============================================================
   HERO
   ============================================================ */

.hero {
  position: relative;
  padding: var(--space-2xl) 0 var(--space-xl);
  text-align: center;
  overflow: hidden;
}

.hero-accent-line {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 3px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    var(--color-accent) 20%,
    var(--color-accent) 80%,
    transparent 100%
  );
  opacity: 0.55;
}

.hero-badge {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  border: var(--border-thin);
  padding: 0.3em 1em;
  margin-bottom: var(--space-lg);
  background: var(--color-surface);
}

#hero-heading {
  font-family: var(--font-sans);
  font-size: clamp(2.2rem, 6vw, 4rem);
  font-weight: 700;
  letter-spacing: var(--ls-heading);
  line-height: 1.15;
  max-width: 18ch;
  margin: 0 auto var(--space-md);
  color: var(--color-text);
}

.hero-subtitle {
  font-size: 1.1rem;
  max-width: 52ch;
  margin: 0 auto var(--space-xl);
  color: var(--color-text-muted);
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-md);
  justify-content: center;
}

/* ---- Buttons ---- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75em 1.8em;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  border: var(--border-thin);
  background: transparent;
  color: var(--color-text);
  cursor: pointer;
  transition: background 0.2s, color 0.2s, border-color 0.2s;
  text-decoration: none;
}

.btn-primary {
  background-color: var(--color-accent);
  color: var(--color-white);
  border-color: var(--color-accent);
}

.btn-primary:hover {
  background-color: var(--color-accent-dim);
  border-color: var(--color-accent-dim);
}

.btn-ghost {
  border-color: var(--color-border);
  color: var(--color-text);
}

.btn-ghost:hover {
  background-color: var(--color-surface);
  border-color: var(--color-accent);
}

/* ============================================================
   METRICS STRIP  (id="metrics")
   ============================================================ */

.metrics-strip {
  padding: var(--space-xl) 0;
  border-top: var(--border-thin);
  border-bottom: var(--border-thin);
  background-color: var(--color-surface);
}

.metrics-strip .container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.metric-card {
  text-align: center;
  padding: var(--space-md);
}

.metric-label {
  display: block;
  font-family: var(--font-mono);
  font-size: 0.8rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: var(--space-xs);
}

.metric-value {
  display: block;
  font-family: var(--font-mono);
  font-size: clamp(2.5rem, 5vw, 3.5rem);
  font-weight: 700;
  letter-spacing: var(--ls-display);
  line-height: 1.1;
  color: var(--color-text);
  margin-bottom: var(--space-sm);
}

.metric-unit {
  font-size: 0.6em;
  font-weight: 500;
  color: var(--color-text-muted);
}

.metric-desc {
  font-size: 0.9rem;
  color: var(--color-text-muted);
  line-height: 1.55;
  max-width: 28ch;
  margin: 0 auto;
}

/* ============================================================
   FEATURES SECTION
   ============================================================ */

.features-section {
  padding: var(--space-2xl) 0;
}

.section-heading {
  text-align: center;
  font-family: var(--font-sans);
  font-size: clamp(1.6rem, 4vw, 2.2rem);
  font-weight: 700;
  letter-spacing: var(--ls-heading);
  margin-bottom: var(--space-xl);
  color: var(--color-text);
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.feature-card {
  background: var(--color-surface);
  border: var(--border-thin);
  padding: var(--space-xl) var(--space-lg);
  transition: border-color 0.2s, transform 0.2s;
}

.feature-card:hover {
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.feature-icon {
  color: var(--color-accent);
  margin-bottom: var(--space-md);
}

.feature-card h3 {
  font-family: var(--font-sans);
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  margin-bottom: var(--space-sm);
  color: var(--color-text);
}

.feature-card p {
  font-size: 0.95rem;
  color: var(--color-text-muted);
  line-height: 1.65;
}

/* ============================================================
   TESTIMONIAL
   ============================================================ */

.testimonial-section {
  padding: var(--space-2xl) 0;
  background-color: var(--color-surface);
  border-top: var(--border-thin);
  border-bottom: var(--border-thin);
}

.testimonial-quote {
  max-width: 640px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote p {
  font-size: 1.25rem;
  font-style: italic;
  line-height: 1.7;
  color: var(--color-text);
  margin-bottom: var(--space-lg);
  position: relative;
}

/* Decorative opening quote mark */
.testimonial-quote p::before {
  content: "\201C";
  display: block;
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 4rem;
  line-height: 1;
  color: var(--color-accent);
  margin-bottom: var(--space-md);
  opacity: 0.45;
  letter-spacing: 0;
}

.testimonial-quote footer {
  font-size: 0.95rem;
  color: var(--color-text-muted);
}

.testimonial-quote cite {
  font-style: normal;
}

.testimonial-quote cite strong {
  display: block;
  color: var(--color-text);
  margin-bottom: 2px;
}

.testimonial-quote cite span {
  font-size: 0.85rem;
  letter-spacing: 0.03em;
}

/* ============================================================
   FOOTER
   ============================================================ */

.site-footer {
  padding: var(--space-xl) 0 var(--space-md);
  border-top: var(--border-thin);
  background: var(--color-bg);
  color: var(--color-text-muted);
}

.footer-top {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: flex-start;
  gap: var(--space-lg);
  margin-bottom: var(--space-xl);
}

.footer-brand {
  max-width: 340px;
}

.footer-logo {
  font-family: var(--font-mono);
  font-size: 1.25rem;
  font-weight: 600;
  letter-spacing: var(--ls-display);
  color: var(--color-accent);
  display: block;
  margin-bottom: var(--space-sm);
}

.footer-brand p {
  font-size: 0.9rem;
  line-height: 1.55;
}

.footer-social {
  display: flex;
  gap: var(--space-md);
  align-items: center;
}

.social-link {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border: var(--border-thin);
  color: var(--color-text-muted);
  transition: color 0.2s, border-color 0.2s, background 0.2s;
}

.social-link:hover {
  color: var(--color-accent);
  border-color: var(--color-accent);
  background: var(--color-surface);
}

.social-link svg {
  width: 20px;
  height: 20px;
}

.footer-bottom {
  text-align: center;
  font-size: 0.8rem;
  border-top: var(--border-thin);
  padding-top: var(--space-lg);
  color: var(--color-text-muted);
}

.footer-tagline {
  margin-top: var(--space-xs);
  font-style: italic;
}

/* ============================================================
   RESPONSIVE BREAKPOINTS
   ============================================================ */

/* Tablet — 1024px and below */
@media (max-width: 1024px) {
  .feature-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Small tablet / large phone — 768px and below */
@media (max-width: 768px) {
  :root {
    --space-xl:  3rem;
    --space-2xl: 4rem;
  }

  .container {
    padding: 0 var(--space-md);
  }

  .site-header .container {
    height: 56px;
  }

  .hero {
    padding: var(--space-xl) 0 var(--space-lg);
  }

  .metrics-strip .container {
    grid-template-columns: 1fr;
    gap: var(--space-md);
  }

  .metric-card {
    padding: var(--space-sm) 0;
    border-bottom: var(--border-thin);
  }

  .metric-card:last-child {
    border-bottom: none;
  }

  .feature-grid {
    grid-template-columns: 1fr 1fr;
  }

  .footer-top {
    flex-direction: column;
    text-align: center;
    align-items: center;
  }

  .footer-brand {
    max-width: 100%;
  }
}

/* Mobile — 480px and below */
@media (max-width: 480px) {
  :root {
    --space-lg:  1.25rem;
    --space-xl:  2rem;
    --space-2xl: 3rem;
  }

  .site-header .container {
    flex-direction: column;
    height: auto;
    padding: var(--space-sm) 0;
    gap: var(--space-sm);
  }

  .nav-links {
    gap: var(--space-md);
  }

  #hero-heading {
    font-size: 1.8rem;
  }

  .hero-subtitle {
    font-size: 1rem;
  }

  .hero-actions {
    flex-direction: column;
    align-items: center;
  }

  .btn {
    width: 100%;
    max-width: 280px;
  }

  .feature-grid {
    grid-template-columns: 1fr;
  }

  .feature-card {
    padding: var(--space-lg);
  }

  .testimonial-quote p {
    font-size: 1.05rem;
  }

  .footer-social {
    justify-content: center;
  }
}

