<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Murmur — Open-Source Reliability Harness for Coding Agents</title>
  <meta name="description" content="Murmur stress-tests your coding agents across thousands of tasks, surfacing regressions and silent failures before they hit production.">
  <link rel="stylesheet" href="styles.css">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;700&display=swap" rel="stylesheet">
</head>
<body>

  <header class="site-header">
    <div class="container">
      <a href="#" class="logo" aria-label="Murmur home">Murmur</a>
      <nav class="nav-links" aria-label="Primary navigation">
        <a href="#features">Features</a>
        <a href="#metrics">Metrics</a>
        <a href="#testimonial">Testimonial</a>
      </nav>
    </div>
  </header>

  <main>

    <!-- Hero Section -->
    <section class="hero" aria-labelledby="hero-heading">
      <div class="container">
        <span class="hero-badge">Open-source &middot; Apache 2.0</span>
        <h1 id="hero-heading">Every murmur in your agent pipeline, caught before it fails.</h1>
        <p class="hero-subtitle">
          Murmur is the open-source reliability harness that stress-tests coding agents across thousands of
          discrete tasks — flagging regressions, hallucinations, and silent drift the moment they appear.
        </p>
        <div class="hero-actions">
          <a href="#" class="btn btn-primary">Star on GitHub</a>
          <a href="#" class="btn btn-ghost">Read the docs &rarr;</a>
        </div>
      </div>
      <div class="hero-accent-line" aria-hidden="true"></div>
    </section>

    <!-- Metrics Strip -->
    <section id="metrics" class="metrics-strip" aria-label="Reliability metrics">
      <div class="container">
        <div class="metric-card">
          <span class="metric-label">pass@1</span>
          <strong class="metric-value">94.7<span class="metric-unit">%</span></strong>
