  flex-direction: column;
  gap: 0.15rem;
}

.quote-author {
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--text);
  letter-spacing: 0.03em;
}

.quote-role {
  font-size: 0.8rem;
  color: var(--text-muted);
  letter-spacing: 0.03em;
}

