    flex-wrap: wrap;
    justify-content: space-between;
    text-align: left;
  }
}

.footer-brand {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.footer-logo {
  font-family: var(--font-mono);
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--text);
}

.footer-tagline {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-bottom: 0;
}

.footer-social {
  display: flex;
  gap: var(--spacing-md);
  flex-wrap: wrap;
  justify-content: center;
}

.social-link {
  font-size: 0.8rem;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  text-transform: uppercase;
