  padding-bottom: 2px;
  transition: color 0.2s ease, border-color 0.2s ease;
}

.social-link:hover {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.footer-copy {
  font-size: 0.7rem;
  color: var(--text-muted);
  letter-spacing: 0.04em;
  margin-bottom: 0;
  width: 100%;
}

@media (min-width: 640px) {
