  outline-offset: 2px;
}

button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* ===== Small-screen refinements (320px+) ===== */
@media (max-width: 399px) {
  .site-nav {
    gap: var(--spacing-sm);
