  .site-nav a {
    font-size: 0.75rem;
    letter-spacing: 0.03em;
  }

  .hero-actions {
    flex-direction: column;
    width: 100%;
  }

  .hero-actions .btn {
    width: 100%;
  }

  .metric {
    padding: var(--spacing-sm);
  }

  .footer-social {
    gap: var(--spacing-sm);
  }
