/* ===== CSS Custom Properties ===== */
:root {
  --bg: #e4e4e0;
  --accent: #e8192a;
  --accent-hover: #c41220;
  --text: #1a1a1a;
  --text-secondary: #555555;
  --text-muted: #777777;
  --border: #cccccc;
  --border-light: #d6d6d2;
  --card-bg: #ededeb;
  --white: #fafaf8;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 2rem;
  --spacing-lg: 4rem;
  --spacing-xl: 6rem;
  --max-width: 1100px;
  --font-mono: 'SF Mono', 'Fira Code', 'Fira Mono', 'Roboto Mono',
    'Cascadia Code', Consolas, monospace;
  --font-sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto,
    'Helvetica Neue', Arial, sans-serif;
  --border-width: 1px;
}

/* ===== CSS Reset & Base ===== */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

main {
  flex: 1;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: var(--accent);
  text-decoration: none;
  transition: color 0.2s ease, border-color 0.2s ease;
}

a:hover {
  color: var(--accent-hover);
}

/* ===== Container ===== */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-sm);
}

@media (min-width: 640px) {
  .container {
    padding: 0 var(--spacing-md);
  }
}

@media (min-width: 960px) {
  .container {
    padding: 0 var(--spacing-lg);
  }
}

/* ===== Typography ===== */
h1,
h2,
h3,
h4,
h5,
h6 {
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: 0.05em;
  color: var(--text);
}

h1 {
  font-size: clamp(1.75rem, 4vw, 2.75rem);
  letter-spacing: 0.06em;
}

h2 {
  font-size: clamp(1.35rem, 3vw, 1.85rem);
  letter-spacing: 0.05em;
}

h3 {
  font-size: clamp(1.1rem, 2vw, 1.3rem);
  letter-spacing: 0.04em;
}

p {
  margin-bottom: var(--spacing-sm);
  color: var(--text-secondary);
}

/* ===== Visually Hidden (accessible) ===== */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ===== Site Header ===== */
.site-header {
  border-bottom: var(--border-width) solid var(--border);
  background-color: var(--bg);
  position: sticky;
  top: 0;
  z-index: 10;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}

.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 56px;
}

@media (min-width: 640px) {
  .site-header .container {
    height: 64px;
  }
}

.logo {
  font-family: var(--font-mono);
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--text);
  text-transform: lowercase;
  transition: color 0.2s ease;
}

.logo:hover {
  color: var(--accent);
}

.site-nav {
  display: flex;
  gap: var(--spacing-md);
  align-items: center;
}

.site-nav a {
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--text-secondary);
  text-transform: uppercase;
  transition: color 0.2s ease;
}

.site-nav a:hover {
  color: var(--accent);
}

/* ===== Hero Section ===== */
.hero {
  padding: var(--spacing-xl) 0 var(--spacing-lg);
  text-align: center;
}

@media (min-width: 640px) {
  .hero {
    padding: var(--spacing-xl) 0;
  }
}

.hero .container {
  max-width: 800px;
}

.hero h1 {
  margin-bottom: var(--spacing-md);
  letter-spacing: 0.07em;
}

.hero-subhead {
  font-size: clamp(1rem, 2vw, 1.2rem);
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-sm);
  justify-content: center;
  align-items: center;
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.7rem 1.6rem;
  font-size: 0.9rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  border-radius: 0;
  border: var(--border-width) solid transparent;
  cursor: pointer;
  transition: background-color 0.2s ease, color 0.2s ease,
    border-color 0.2s ease, transform 0.15s ease;
  text-transform: uppercase;
  font-family: var(--font-sans);
}

.btn:active {
  transform: scale(0.97);
}

.btn-primary {
  background-color: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.btn-primary:hover {
  background-color: var(--accent-hover);
  border-color: var(--accent-hover);
  color: #fff;
}

.btn-ghost {
  background-color: transparent;
  color: var(--text);
  border-color: var(--border);
}

.btn-ghost:hover {
  border-color: var(--text);
  color: var(--text);
}

/* ===== Metrics Strip ===== */
.metrics-strip {
  padding: var(--spacing-lg) 0;
  border-top: var(--border-width) solid var(--border);
  border-bottom: var(--border-width) solid var(--border);
  background-color: var(--card-bg);
}

.metrics-heading {
  text-align: center;
  margin-bottom: var(--spacing-md);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
}

.metrics-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-md);
  margin-bottom: var(--spacing-md);
}

@media (min-width: 640px) {
  .metrics-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: var(--spacing-lg);
  }
}

.metric {
  text-align: center;
  padding: var(--spacing-md);
  border: var(--border-width) solid var(--border-light);
  background-color: var(--white);
  transition: border-color 0.25s ease;
}

.metric:hover {
  border-color: var(--accent);
}

.metric-label {
  display: block;
  font-family: var(--font-mono);
  font-size: 0.8rem;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  text-transform: uppercase;
  margin-bottom: var(--spacing-xs);
}

.metric-label em {
  font-style: normal;
  font-size: 0.7rem;
  color: var(--text-muted);
  letter-spacing: 0.04em;
}

.metric-value {
  display: block;
  font-family: var(--font-mono);
  font-size: clamp(2.2rem, 5vw, 3rem);
  font-weight: 700;
  color: var(--text);
  letter-spacing: 0.02em;
  line-height: 1.1;
  margin-bottom: var(--spacing-xs);
}

.metric-note {
  display: block;
  font-size: 0.8rem;
  color: var(--text-muted);
  line-height: 1.5;
}

.metrics-disclaimer {
  text-align: center;
  font-size: 0.75rem;
  color: var(--text-muted);
  letter-spacing: 0.03em;
}

.metrics-disclaimer time {
  font-weight: 500;
  color: var(--text-secondary);
}

/* ===== Features Section ===== */
.features {
  padding: var(--spacing-xl) 0;
}

.section-heading {
  text-align: center;
  margin-bottom: var(--spacing-lg);
}

.cards {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-md);
}

@media (min-width: 640px) {
  .cards {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 960px) {
  .cards {
    grid-template-columns: repeat(3, 1fr);
    gap: var(--spacing-lg);
  }
}

.card {
  background-color: var(--card-bg);
  border: var(--border-width) solid var(--border-light);
  padding: var(--spacing-md);
  transition: border-color 0.25s ease, transform 0.2s ease;
}

.card:hover {
  border-color: var(--accent);
  transform: translateY(-2px);
}

.card-icon {
  margin-bottom: var(--spacing-sm);
  display: flex;
  align-items: center;
}

/* Thin-bordered geometric icons */
.icon-diamond,
.icon-square,
.icon-frames {
  display: inline-block;
  border: var(--border-width) solid var(--accent);
  transition: background-color 0.25s ease;
}

.icon-diamond {
  width: 16px;
  height: 16px;
  transform: rotate(45deg);
  margin: 4px;
}

.icon-square {
  width: 20px;
  height: 20px;
}

.icon-frames {
  width: 20px;
  height: 20px;
  position: relative;
}

.icon-frames::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 12px;
  height: 12px;
  border: var(--border-width) solid var(--accent);
  transition: background-color 0.25s ease;
}

.card:hover .icon-diamond,
.card:hover .icon-square,
.card:hover .icon-frames {
  background-color: rgba(232, 25, 42, 0.08);
}

.card:hover .icon-frames::after {
  background-color: rgba(232, 25, 42, 0.08);
}

.card-heading {
  margin-bottom: var(--spacing-sm);
}

.card-body {
  font-size: 0.9rem;
  line-height: 1.65;
  color: var(--text-secondary);
  margin-bottom: 0;
}

/* ===== Testimonial ===== */
.testimonial {
  padding: var(--spacing-xl) 0;
  border-top: var(--border-width) solid var(--border);
}

.testimonial .container {
  max-width: 720px;
}

.quote blockquote {
  border-left: 3px solid var(--accent);
  padding-left: var(--spacing-md);
  margin: 0 0 var(--spacing-md) 0;
}

.quote blockquote p {
  font-size: clamp(1rem, 2.5vw, 1.2rem);
  line-height: 1.7;
  font-style: italic;
  color: var(--text);
  margin-bottom: 0;
}

.quote figcaption {
  padding-left: calc(var(--spacing-md) + 3px);
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.quote-author {
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--text);
  letter-spacing: 0.03em;
}

.quote-role {
  font-size: 0.8rem;
  color: var(--text-muted);
  letter-spacing: 0.03em;
}

/* ===== Site Footer ===== */
.site-footer {
  border-top: var(--border-width) solid var(--border);
  padding: var(--spacing-lg) 0;
  background-color: var(--card-bg);
}

.site-footer .container {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
  align-items: center;
  text-align: center;
}

@media (min-width: 640px) {
  .site-footer .container {
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: space-between;
    text-align: left;
  }
}

.footer-brand {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.footer-logo {
  font-family: var(--font-mono);
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--text);
}

.footer-tagline {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-bottom: 0;
}

.footer-social {
  display: flex;
  gap: var(--spacing-md);
  flex-wrap: wrap;
  justify-content: center;
}

.social-link {
  font-size: 0.8rem;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  text-transform: uppercase;
  border-bottom: var(--border-width) solid transparent;
  padding-bottom: 2px;
  transition: color 0.2s ease, border-color 0.2s ease;
}

.social-link:hover {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.footer-copy {
  font-size: 0.7rem;
  color: var(--text-muted);
  letter-spacing: 0.04em;
