args.content:
:root {
  --bg: #e4e4e0;
  --accent: #e8192a;
  --accent-hover: #b5141e;
  --text: #1a1a1a;
  --text-light: #555;
  --border: #ccc;
  --card-bg: #f9f9f6;
  --max-width: 1200px;
  --spacing: 1.5rem;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
}

h1, h2, h3 {
  letter-spacing: 0.15em;
  text-transform: uppercase;
  font-weight: 700;
}

a {
  color: var(--accent);
  text-decoration: none;
  transition: color 0.2s;
}
a:hover {
  color: var(--accent-hover);
  text-decoration: underline;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing);
}

/* Header */
header {
  border-bottom: 1px solid var(--border);
  padding: 1rem 0;
}
header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.logo {
  font-weight: 900;
  font-size: 1.5rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--accent);
}
nav a {
  margin-left: 2rem;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text);
}
nav a:hover {
  color: var(--accent);
}

/* Hero */
.hero {
  text-align: center;
