:root {
  --bg: #e4e4e0;
  --accent: #e8192a;
  --accent-hover: #b5141e;
  --text: #1a1a1a;
  --text-light: #555;
  --border: #ccc;
  --card-bg: #f9f9f6;
  --max-width: 1200px;
  --spacing: 1.5rem;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
}

h1, h2, h3 {
  letter-spacing: 0.15em;
  text-transform: uppercase;
  font-weight: 700;
}

a {
  color: var(--accent);
  text-decoration: none;
  transition: color 0.2s;
}

a:hover {
  color: var(--accent-hover);
  text-decoration: underline;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing);
}

/* Header */
header {
  border-bottom: 1px solid var(--border);
  padding: 1rem 0;
}

header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.logo {
  font-weight: 900;
  font-size: 1.5rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--accent);
}

nav a {
  margin-left: 2rem;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text);
}

nav a:hover {
  color: var(--accent);
}

/* Hero */
.hero {
  text-align: center;
  padding: 4rem 1rem;
}

.hero h1 {
  font-size: clamp(2rem, 8vw, 4rem);
  line-height: 1.2;
  margin-bottom: 1rem;
}

.hero p {
  font-size: 1.125rem;
  max-width: 600px;
  margin: 0 auto 2rem auto;
  color: var(--text-light);
}

.btn {
  display: inline-block;
  background: var(--accent);
  color: white;
  padding: 0.75rem 2rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  border: 2px solid var(--accent);
  transition: background 0.2s, color 0.2s;
}

.btn:hover {
  background: transparent;
  color: var(--accent);
  text-decoration: none;
}

/* Metrics */
.metrics {
  background: #fff;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 2rem 0;
}

.metrics .container {
  display: flex;
  justify-content: space-around;
  flex-wrap: wrap;
  gap: 2rem;
}

.stat {
  text-align: center;
}

.stat-value {
  font-family: 'SF Mono', 'Consolas', 'Courier New', monospace;
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--accent);
}

.stat-label {
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-light);
}

/* Features */
.features {
  padding: 4rem 1rem;
}

.features h2 {
  text-align: center;
  margin-bottom: 3rem;
  font-size: 2rem;
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
}

.card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  padding: 2rem;
  text-align: center;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.card:hover {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent);
}

.card-icon {
  width: 48px;
  height: 48px;
  margin: 0 auto 1.5rem auto;
  color: var(--accent);
}

.card h3 {
  font-size: 1.2rem;
  margin-bottom: 0.75rem;
}

.card p {
  color: var(--text-light);
}

/* Testimonial */
.testimonial {
  background: #fff;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 4rem 1rem;
  text-align: center;
}

.testimonial blockquote {
  max-width: 700px;
  margin: 0 auto;
  font-size: 1.25rem;
  font-style: italic;
  color: var(--text);
  position: relative;
}

.testimonial blockquote::before {
  content: "“";
  font-size: 4rem;
  color: var(--accent);
  line-height: 0;
  position: absolute;
  left: -1.5rem;
  top: 0.5rem;
}

.testimonial cite {
  display: block;
  margin-top: 1rem;
  font-style: normal;
  font-weight: 600;
  color: var(--text-light);
  letter-spacing: 0.05em;
}

/* Footer */
footer {
  padding: 2rem 1rem;
  border-top: 1px solid var(--border);
  text-align: center;
}

.footer-links {
  display: flex;
  justify-content: center;
  gap: 2rem;
  margin-bottom: 1rem;
  flex-wrap: wrap;
}

.footer-links a {
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.footer-copy {
  font-size: 0.8rem;
  color: var(--text-light);
}

/* Responsive */
@media (max-width: 600px) {
  .hero h1 {
    font-size: 2rem;
  }

  .metrics .container {
    flex-direction: column;
    align-items: center;
  }

  .stat-value {
    font-size: 2rem;
  }

  header .container {
    flex-direction: column;
    align-items: center;
  }

  nav a {
    margin-left: 1rem;
  }
}

