/* ============================================================
   Murmur — Open-Source Reliability Harness
   Tech-Noir Palette | CSS Variables | 320px–1200px Responsive
   ============================================================ */

:root {
  /* --- Color Palette --- */
  --color-bg:           #e4e4e0;      /* light gray background */
  --color-surface:      #f5f5f2;      /* slightly lighter card surface */
  --color-accent:       #e8192a;      /* accent red */
  --color-accent-hover: #c41422;      /* darker red on hover */
  --color-text:         #1a1a1a;      /* near-black for body text */
  --color-text-muted:   #5c5c57;      /* muted gray for secondary text */
  --color-border:       #cecec7;      /* thin border gray */
  --color-strip-bg:     #1a1a1a;      /* dark background for metrics strip */
  --color-strip-text:   #e4e4e0;      /* light text on dark strip */
  --color-strip-accent: #e8192a;      /* accent on dark strip */

  /* --- Typography --- */
  --font-sans:   'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  --font-mono:   'JetBrains Mono', 'Fira Code', 'Cascadia Code', 'Consolas', monospace;
  --font-heading: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;

  /* --- Spacing Scale --- */
  --space-xs:   0.25rem;
  --space-sm:   0.5rem;
  --space-md:   1rem;
  --space-lg:   1.5rem;
  --space-xl:   2rem;
  --space-2xl:  3rem;
  --space-3xl:  4rem;
  --space-4xl:  6rem;

  /* --- Layout --- */
  --max-width:  1100px;
  --border-radius: 2px;
  --border-width: 1px;
  --letter-spacing-heading: 0.08em;
  --letter-spacing-wide: 0.12em;
}

/* ============================================================
   RESET & BASE
   ============================================================ */

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 100%;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color 0.2s ease, border-color 0.2s ease, background-color 0.2s ease;
}

ul {
  list-style: none;
}

/* ============================================================
   SKIP LINK
   ============================================================ */

.skip-link {
  position: absolute;
  top: -100%;
  left: var(--space-md);
  background: var(--color-accent);
  color: #fff;
  padding: var(--space-sm) var(--space-md);
  font-size: 0.875rem;
  font-weight: 600;
  z-index: 1000;
  border-radius: 0 0 var(--border-radius) var(--border-radius);
}

.skip-link:focus {
  top: 0;
}

/* ============================================================
   CONTAINER
   ============================================================ */

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

@media (min-width: 768px) {
  .container {
    padding: 0 var(--space-2xl);
  }
}

@media (min-width: 1024px) {
  .container {
    padding: 0 var(--space-3xl);
  }
}

/* ============================================================
   HEADER
   ============================================================ */

.site-header {
  border-bottom: var(--border-width) solid var(--color-border);
  background-color: var(--color-bg);
  position: sticky;
  top: 0;
  z-index: 100;
}

.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: var(--space-md);
  padding-bottom: var(--space-md);
}

.logo {
  font-family: var(--font-mono);
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: var(--letter-spacing-wide);
  text-transform: lowercase;
  color: var(--color-text);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.logo-icon {
  color: var(--color-accent);
  font-size: 1rem;
  line-height: 1;
}

.site-nav ul {
  display: flex;
  gap: var(--space-lg);
  align-items: center;
}

.site-nav a {
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: var(--letter-spacing-heading);
  text-transform: uppercase;
  color: var(--color-text-muted);
  padding: var(--space-xs) 0;
  border-bottom: 1px solid transparent;
  transition: color 0.2s ease, border-color 0.2s ease;
}

.site-nav a:hover,
.site-nav a:focus-visible {
  color: var(--color-accent);
  border-bottom-color: var(--color-accent);
}

/* ============================================================
   HERO
   ============================================================ */

.hero {
  padding: var(--space-4xl) 0 var(--space-3xl);
  text-align: center;
  border-bottom: var(--border-width) solid var(--color-border);
}

.hero h1 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: var(--letter-spacing-heading);
  color: var(--color-text);
  max-width: 900px;
  margin: 0 auto var(--space-lg);
  text-transform: none;
}

.hero h1 em {
  font-style: italic;
  color: var(--color-accent);
  font-weight: 700;
}

.hero-subtitle {
  font-size: clamp(1rem, 2.2vw, 1.25rem);
  line-height: 1.7;
  color: var(--color-text-muted);
  max-width: 680px;
  margin: 0 auto var(--space-2xl);
  font-weight: 400;
}

.cta-button {
  display: inline-block;
  background-color: var(--color-accent);
  color: #fff;
  font-family: var(--font-mono);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: var(--letter-spacing-wide);
  text-transform: uppercase;
  padding: var(--space-md) var(--space-2xl);
  border: none;
  cursor: pointer;
  transition: background-color 0.25s ease, transform 0.15s ease, box-shadow 0.25s ease;
  border-radius: var(--border-radius);
  box-shadow: 0 1px 3px rgba(232, 25, 42, 0.25);
}

.cta-button:hover,
.cta-button:focus-visible {
  background-color: var(--color-accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(232, 25, 42, 0.35);
}

.cta-button:active {
  transform: translateY(0);
  box-shadow: 0 1px 2px rgba(232, 25, 42, 0.3);
}

/* ============================================================
   METRICS STRIP
   ============================================================ */

.metrics-strip {
  background-color: var(--color-strip-bg);
  color: var(--color-strip-text);
  padding: var(--space-3xl) 0;
  border-bottom: var(--border-width) solid var(--color-border);
}

.metrics-heading {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: var(--letter-spacing-wide);
  text-transform: uppercase;
  color: var(--color-strip-accent);
  text-align: center;
  margin-bottom: var(--space-2xl);
}

.metrics-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-xl);
  text-align: center;
}

@media (min-width: 600px) {
  .metrics-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.metric-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-xs);
  padding: var(--space-lg);
  border: var(--border-width) solid rgba(228, 228, 224, 0.15);
  border-radius: var(--border-radius);
  transition: border-color 0.3s ease, background-color 0.3s ease;
}

.metric-card:hover {
  border-color: var(--color-strip-accent);
  background-color: rgba(232, 25, 42, 0.05);
}

.metric-label {
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: var(--letter-spacing-wide);
  text-transform: uppercase;
  color: var(--color-strip-accent);
  opacity: 0.8;
}

.metric-label sup {
  font-size: 0.625rem;
}

.metric-value {
  font-family: var(--font-mono);
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-strip-text);
  line-height: 1;
}

.metric-note {
  font-size: 0.75rem;
  color: rgba(228, 228, 224, 0.55);
  letter-spacing: 0.03em;
}

/* ============================================================
   FEATURES
   ============================================================ */

.features {
  padding: var(--space-4xl) 0;
  border-bottom: var(--border-width) solid var(--color-border);
}

.section-heading {
  font-family: var(--font-heading);
  font-size: clamp(1.5rem, 3.5vw, 2rem);
  font-weight: 700;
  letter-spacing: var(--letter-spacing-heading);
  text-align: center;
  margin-bottom: var(--space-3xl);
  color: var(--color-text);
}

.feature-cards {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-xl);
}

@media (min-width: 700px) {
  .feature-cards {
    grid-template-columns: repeat(3, 1fr);
  }
}

.feature-card {
  background-color: var(--color-surface);
  border: var(--border-width) solid var(--color-border);
  padding: var(--space-2xl) var(--space-xl);
  border-radius: var(--border-radius);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--space-md);
  transition: border-color 0.3s ease, box-shadow 0.3s ease, transform 0.2s ease;
}

.feature-card:hover {
  border-color: var(--color-accent);
  box-shadow: 0 2px 12px rgba(232, 25, 42, 0.08);
  transform: translateY(-2px);
}

.feature-icon {
  font-size: 1.5rem;
  color: var(--color-accent);
  line-height: 1;
  margin-bottom: var(--space-xs);
}

.feature-title {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: var(--letter-spacing-heading);
  color: var(--color-text);
  line-height: 1.3;
}

.feature-title sup {
  font-size: 0.7rem;
}

.feature-desc {
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--color-text-muted);
  flex-grow: 1;
}

/* ============================================================
   TESTIMONIAL
   ============================================================ */

.testimonial {
  padding: var(--space-4xl) 0;
  border-bottom: var(--border-width) solid var(--color-border);
}

.testimonial-quote {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote p {
  font-size: clamp(1.125rem, 2.5vw, 1.375rem);
  line-height: 1.75;
  color: var(--color-text);
  font-weight: 400;
  font-style: italic;
  position: relative;
  padding: 0 var(--space-md);
}

.testimonial-quote p::before {
  content: '\201C';
  font-family: var(--font-heading);
  font-size: 4rem;
  color: var(--color-accent);
  position: absolute;
  top: -1.5rem;
  left: -0.5rem;
  line-height: 1;
  opacity: 0.3;
}

.testimonial-attribution {
  margin-top: var(--space-xl);
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: var(--letter-spacing-heading);
  color: var(--color-text-muted);
  font-style: normal;
  display: block;
}

.testimonial-attribution cite {
  font-style: normal;
}

/* ============================================================
   FOOTER
   ============================================================ */

.site-footer {
  background-color: var(--color-strip-bg);
  color: var(--color-strip-text);
  padding: var(--space-3xl) 0 var(--space-lg);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-xl);
  margin-bottom: var(--space-2xl);
}

@media (min-width: 600px) {
  .footer-grid {
    grid-template-columns: 2fr 1fr 1fr;
  }
}

.footer-brand {
  grid-column: 1 / -1;
}

@media (min-width: 600px) {
  .footer-brand {
    grid-column: auto;
  }
}

.footer-logo {
  font-family: var(--font-mono);
  font-size: 1.125rem;
  font-weight: 700;
  letter-spacing: var(--letter-spacing-wide);
  text-transform: lowercase;
  color: var(--color-strip-text);
  display: block;
  margin-bottom: var(--space-sm);
}

.footer-tagline {
  font-size: 0.8125rem;
  color: rgba(228, 228, 224, 0.55);
  line-height: 1.5;
}

.footer-heading {
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: var(--letter-spacing-wide);
  text-transform: uppercase;
  color: var(--color-strip-accent);
  margin-bottom: var(--space-md);
  opacity: 0.8;
}

.footer-links ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.footer-links a {
  font-size: 0.8125rem;
  color: rgba(228, 228, 224, 0.7);
  transition: color 0.2s ease;
  padding: 2px 0;
}

.footer-links a:hover,
.footer-links a:focus-visible {
  color: var(--color-strip-accent);
  text-decoration: none;
}

.footer-bottom {
  border-top: var(--border-width) solid rgba(228, 228, 224, 0.12);
  padding-top: var(--space-lg);
  margin-top: var(--space-lg);
  text-align: center;
}

.footer-bottom p {
  font-size: 0.75rem;
  color: rgba(228, 228, 224, 0.4);
  letter-spacing: 0.02em;
}

/* ============================================================
   FOCUS-VISIBLE GLOBAL
   ============================================================ */

:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 1px;
}

/* ============================================================
   RESPONSIVE FINE-TUNING
   ============================================================ */

@media (max-width: 480px) {
  .hero {
    padding: var(--space-2xl) 0 var(--space-xl);
  }

  .hero h1 {
    letter-spacing: 0.04em;
  }

  .features {
    padding: var(--space-2xl) 0;
  }

  .testimonial {
    padding: var(--space-2xl) 0;
  }

  .site-nav ul {
    gap: var(--space-md);
  }

  .site-nav a {
    font-size: 0.75rem;
  }

  .feature-card {
    padding: var(--space-lg);
  }

  .metrics-strip {
    padding: var(--space-2xl) 0;
  }

  .cta-button {
    padding: var(--space-md) var(--space-lg);
    font-size: 0.8125rem;
  }
}

@media (min-width: 481px) and (max-width: 699px) {
  .feature-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .feature-cards .feature-card:last-child {
    grid-column: 1 / -1;
    max-width: 400px;
    justify-self: center;
    width: 100%;
  }
}

@media (min-width: 700px) and (max-width: 900px) {
  .feature-card {
    padding: var(--space-lg);
  }
}

/* ============================================================
   PRINT STYLES
   ============================================================ */

@media print {
  .site-header,
  .site-footer,
  .cta-button,
  .skip-link {
    display: none;
  }

  body {
    background: #fff;
    color: #000;
  }

  .metrics-strip {
    background: #fff;
    color: #000;
    border: 1px solid #ccc;
  }

  .metrics-strip .metric-value {
    color: #000;
  }

  .metrics-strip .metric-label,
  .metrics-strip .metric-note {
    color: #555;
  }
}

