/* ===== CSS Custom Properties (Tech-Noir Palette) ===== */
:root {
    --color-bg:          #e4e4e0;
    --color-surface:     #f0f0ec;
    --color-border:      #c8c8c0;
    --color-border-light:#d6d6cf;
    --color-text:        #1a1a18;
    --color-text-muted:  #6b6b62;
    --color-accent:      #e8192a;
    --color-accent-dark: #c41523;

    --font-sans:  'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
    --font-mono:  'SF Mono', 'Cascadia Code', 'Consolas', 'Courier New', monospace;

    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 2rem;
    --spacing-lg: 4rem;
    --spacing-xl: 6rem;

    --max-width: 1100px;
    --border-thin: 1px;
    --radius-sm: 6px;
    --radius-md: 8px;

    --letter-spacing-heading: 0.06em;
    --letter-spacing-wide:    0.08em;
}

/* ===== Reset & Base ===== */
*,
*::before,
*::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    font-size: 16px;
    -webkit-text-size-adjust: 100%;
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-sans);
    background-color: var(--color-bg);
    color: var(--color-text);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

img, svg {
    display: block;
    max-width: 100%;
}

a {
    color: var(--color-text);
    text-decoration-thickness: 1px;
    text-underline-offset: 3px;
    transition: color 0.2s ease;
}

a:hover {
    color: var(--color-accent);
}

/* ===== Utility ===== */
.container {
    width: 100%;
    max-width: var(--max-width);
    margin-inline: auto;
    padding-inline: var(--spacing-md);
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

/* ===== Typography ===== */
h1, h2, h3, .section-heading {
    letter-spacing: var(--letter-spacing-heading);
    font-weight: 600;
    line-height: 1.2;
}

.section-heading {
    font-size: 1.75rem;
    margin-bottom: var(--spacing-md);
    color: var(--color-text);
    border-bottom: var(--border-thin) solid var(--color-border);
    padding-bottom: var(--spacing-sm);
}

/* ===== Header ===== */
.site-header {
    position: sticky;
    top: 0;
    z-index: 50;
    background-color: rgba(228, 228, 224, 0.88);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-bottom: var(--border-thin) solid var(--color-border);
}

.header-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 60px;
}

.logo {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    text-decoration: none;
    color: var(--color-text);
    font-weight: 700;
    font-size: 1.15rem;
    letter-spacing: 0.04em;
}

.logo-text {
    white-space: nowrap;
}

.nav-links {
    display: flex;
    gap: 1.4rem;
    list-style: none;
}

.nav-links a {
    text-decoration: none;
    font-size: 0.875rem;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: var(--letter-spacing-wide);
    color: var(--color-text-muted);
    transition: color 0.2s;
}

.nav-links a:hover {
    color: var(--color-accent);
}

/* ===== Hero ===== */
.hero {
    padding: var(--spacing-xl) 0 var(--spacing-lg);
    text-align: center;
    border-bottom: var(--border-thin) solid var(--color-border);
}

.hero-kicker {
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-sm);
}

.hero-title {
    font-size: clamp(2rem, 6vw, 3.6rem);
    font-weight: 700;
    letter-spacing: 0.03em;
    margin-bottom: var(--spacing-md);
    max-width: 20ch;
    margin-inline: auto;
    line-height: 1.15;
}

.hero-accent {
    color: var(--color-accent);
}

.hero-subtitle {
    font-size: 1.1rem;
    color: var(--color-text-muted);
    max-width: 38rem;
    margin-inline: auto;
    margin-bottom: var(--spacing-md);
    line-height: 1.6;
}

.hero-cta {
    display: flex;
    flex-wrap: wrap;
    gap: var(--spacing-sm);
    justify-content: center;
}

/* ===== Buttons ===== */
.btn {
    display: inline-flex;
    align-items: center;
    padding: 0.8rem 1.8rem;
    border-radius: var(--radius-sm);
    font-weight: 600;
    font-size: 0.95rem;
    letter-spacing: 0.03em;
    text-decoration: none;
    cursor: pointer;
    transition: all 0.2s ease;
    border: var(--border-thin) solid var(--color-border);
    background: transparent;
    color: var(--color-text);
}

.btn-primary {
    background-color: var(--color-accent);
    color: #fff;
    border-color: var(--color-accent);
}

.btn-primary:hover {
    background-color: var(--color-accent-dark);
    border-color: var(--color-accent-dark);
    color: #fff;
}

.btn-outline {
    background: transparent;
    color: var(--color-text);
    border-color: var(--color-border);
}

.btn-outline:hover {
    border-color: var(--color-accent);
    color: var(--color-accent);
}

/* ===== Features ===== */
.features {
    padding: var(--spacing-xl) 0;
}

.features-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(270px, 1fr));
    gap: var(--spacing-md);
}

.feature-card {
    background: var(--color-surface);
    border: var(--border-thin) solid var(--color-border);
    border-radius: var(--radius-md);
    padding: var(--spacing-md);
    transition: border-color 0.25s ease, box-shadow 0.25s ease;
}

.feature-card:hover {
    border-color: var(--color-accent);
    box-shadow: 0 4px 20px rgba(232, 25, 42, 0.06);
}

.feature-icon {
    margin-bottom: var(--spacing-sm);
    display: flex;
    align-items: center;
}

.feature-title {
    font-size: 1.2rem;
    font-weight: 600;
    margin-bottom: 0.6rem;
    letter-spacing: var(--letter-spacing-heading);
}

.feature-desc {
    font-size: 0.95rem;
    color: var(--color-text-muted);
    line-height: 1.6;
}

/* ===== Metrics Strip ===== */
.metrics-strip {
    background-color: var(--color-surface);
    border-top: var(--border-thin) solid var(--color-border);
    border-bottom: var(--border-thin) solid var(--color-border);
    padding: var(--spacing-lg) 0;
}

.metrics-heading {
    text-align: center;
    margin-bottom: 0.4rem;
    border-bottom: none;
}

.metrics-subtitle {
    text-align: center;
    font-size: 0.9rem;
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-md);
}

.metrics-grid {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--spacing-lg);
    text-align: center;
}

.metric-card {
    min-width: 160px;
    padding: var(--spacing-sm);
}

.metric-label {
    display: block;
    font-family: var(--font-mono);
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--color-text-muted);
    margin-bottom: 0.4rem;
}

.metric-label small {
    font-size: 0.7rem;
    letter-spacing: 0.05em;
    text-transform: none;
}

.metric-value {
    display: block;
    font-family: var(--font-mono);
    font-size: 3.2rem;
    font-weight: 700;
    color: var(--color-text);
    line-height: 1;
    letter-spacing: -0.02em;
}

.metric-unit {
    font-size: 1.6rem;
    font-weight: 400;
}

.metric-note {
    display: block;
    font-size: 0.78rem;
    color: var(--color-text-muted);
    margin-top: 0.4rem;
    font-style: italic;
}

/* ===== Testimonial ===== */
.testimonial {
    padding: var(--spacing-xl) 0;
}

.testimonial-figure {
    max-width: 640px;
    margin: 0 auto;
    text-align: center;
}

.testimonial-quote {
    font-size: 1.25rem;
    line-height: 1.6;
    font-style: italic;
    color: var(--color-text);
    margin-bottom: var(--spacing-md);
    position: relative;
}

.testimonial-quote::before {
    content: "\201C";
    font-size: 4rem;
    line-height: 0;
    color: var(--color-accent);
    opacity: 0.25;
    display: block;
    margin-bottom: 0.5rem;
    font-style: normal;
    font-family: Georgia, serif;
}

.testimonial-attribution {
    border-top: var(--border-thin) solid var(--color-border-light);
    padding-top: var(--spacing-sm);
    font-style: normal;
}

.attribution-name {
    display: block;
    font-weight: 600;
    font-size: 1rem;
    color: var(--color-text);
}

.attribution-title {
    display: block;
    font-size: 0.85rem;
    color: var(--color-text-muted);
    margin-top: 0.2rem;
}

/* ===== Footer ===== */
.site-footer {
    margin-top: auto;
    border-top: var(--border-thin) solid var(--color-border);
    padding: var(--spacing-md) 0;
    font-size: 0.85rem;
}

.footer-inner {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--spacing-sm) var(--spacing-md);
    justify-content: space-between;
}

.footer-brand {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
}

.footer-logo-text {
    font-weight: 700;
    font-size: 1.1rem;
    letter-spacing: 0.04em;
}

.footer-tagline {
    color: var(--color-text-muted);
    font-size: 0.85rem;
}

.footer-social {
    display: flex;
    flex-wrap: wrap;
    gap: 1.2rem;
}

.footer-social a {
    text-decoration: none;
    text-transform: uppercase;
    letter-spacing: var(--letter-spacing-wide);
    font-size: 0.8rem;
    font-weight: 500;
    color: var(--color-text-muted);
    transition: color 0.2s;
}

.footer-social a:hover {
    color: var(--color-accent);
}

.footer-copy {
    width: 100%;
    text-align: center;
    color: var(--color-text-muted);
    font-size: 0.8rem;
    margin-top: var(--spacing-xs);
}

/* ===== Responsive Design ===== */

/* Tablet: 768px and below */
@media (max-width: 768px) {
    :root {
        --spacing-xl: 3.5rem;
        --spacing-lg: 2.5rem;
    }

    .hero-title {
        font-size: 1.9rem;
    }

    .hero-subtitle {
        font-size: 1rem;
    }

    .features-grid {
        grid-template-columns: 1fr;
        gap: var(--spacing-sm);
    }

    .metrics-grid {
        flex-direction: column;
        align-items: center;
        gap: var(--spacing-md);
    }

    .metric-value {
        font-size: 2.6rem;
    }

    .testimonial-quote {
        font-size: 1.1rem;
    }

    .footer-inner {
        flex-direction: column;
        text-align: center;
        gap: var(--spacing-sm);
    }

    .footer-social {
        justify-content: center;
    }
}

/* Mobile: 480px and below */
@media (max-width: 480px) {
    .container {
        padding-inline: var(--spacing-sm);
    }

    .header-inner {
        height: auto;
        padding-block: 0.7rem;
        flex-wrap: wrap;
        gap: 0.5rem;
        justify-content: center;
    }

    .hero {
        padding: var(--spacing-lg) 0 var(--spacing-md);
    }

    .hero-title {
        font-size: 1.55rem;
    }

    .hero-cta {
        flex-direction: column;
        align-items: center;
    }

    .btn {
        width: 100%;
        justify-content: center;
        text-align: center;
    }

    .section-heading {
        font-size: 1.35rem;
    }

    .feature-card {
        padding: var(--spacing-sm);
    }

    .metric-card {
        min-width: auto;
    }

    .metric-value {
        font-size: 2.2rem;
    }

    .testimonial-quote {
        font-size: 1rem;
    }

    .footer-inner {
        gap: 0.8rem;
    }
}

/* Smallest: 320px */
@media (max-width: 360px) {
    .hero-title {
        font-size: 1.35rem;
    }

    .nav-links {
        gap: 0.8rem;
    }

    .nav-links a {
        font-size: 0.75rem;
    }

    .metrics-grid {
        gap: var(--spacing-sm);
    }
}

