/* ============================================================
   Murmur — Reliability Harness for Coding Agents
   Tech-noir palette: bg #e4e4e0, accent #e8192a, thin borders
   Wide letter-spacing on headings. Zero frameworks.
   ============================================================ */

/* ---- Custom Properties ---- */
:root {
  --color-bg:          #e4e4e0;
  --color-bg-alt:      #d9d8d3;
  --color-surface:     #eeedea;
  --color-text:        #1a1a18;
  --color-text-muted:  #5c5c55;
  --color-border:      #c4c3bc;
  --color-accent:      #e8192a;
  --color-accent-dark: #b81421;
  --color-accent-glow: rgba(232, 25, 42, 0.10);

  --font-sans:  'Inter', 'SF Pro Display', 'Segoe UI', system-ui, -apple-system, sans-serif;
  --font-mono:  'JetBrains Mono', 'SF Mono', 'Fira Code', 'Courier New', monospace;

  --ls-heading: 0.06em;
  --ls-label:   0.10em;
  --border:     1px solid var(--color-border);

  --container:  1080px;
  --r-sm:       4px;
  --r-md:       8px;
}

/* ---- Reset ---- */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 100%;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
}

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-width: 320px;
}

a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }

/* ---- Container ---- */
.container {
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 clamp(1rem, 4vw, 2rem);
}

/* ---- Header ---- */
.site-header {
  background: var(--color-surface);
  border-bottom: var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
}

.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 3.75rem;
}

.logo {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 700;
  font-size: 1.125rem;
  letter-spacing: var(--ls-heading);
  text-transform: uppercase;
}

.logo-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--r-sm);
  font-weight: 800;
  font-size: 1rem;
}

.site-nav {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  font-size: 0.875rem;
  letter-spacing: var(--ls-label);
  text-transform: uppercase;
}

.site-nav a {
  position: relative;
  color: var(--color-text-muted);
  transition: color 0.2s;
}

.site-nav a:hover,
.site-nav a:focus-visible {
  color: var(--color-accent);
}

.site-nav a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--color-accent);
  transition: width 0.2s;
}

.site-nav a:hover::after,
.site-nav a:focus-visible::after {
  width: 100%;
}

.nav-cta {
  border: 1px solid var(--color-accent) !important;
  color: var(--color-accent) !important;
  padding: 0.4rem 0.9rem;
  border-radius: var(--r-sm);
  transition: background 0.2s, color 0.2s !important;
}

.nav-cta:hover,
.nav-cta:focus-visible {
  background: var(--color-accent) !important;
  color: #fff !important;
}

.nav-cta::after { display: none; }

/* ---- Hero ---- */
.hero {
  padding: clamp(3rem, 8vw, 5.5rem) 0 clamp(3rem, 6vw, 4rem);
  text-align: center;
  border-bottom: var(--border);
}

.hero-badge {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: var(--ls-label);
  text-transform: uppercase;
  color: var(--color-accent);
  border: var(--border);
  border-radius: 99px;
  padding: 0.35rem 1rem;
  margin-bottom: 1.5rem;
  background: var(--color-accent-glow);
}

.hero-headline {
  font-size: clamp(1.75rem, 5vw, 3.25rem);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: var(--ls-heading);
  max-width: 20ch;
  margin: 0 auto 1rem;
  text-transform: uppercase;
}

.hero-headline em {
  font-style: normal;
  color: var(--color-accent);
}

.hero-subhead {
  font-size: clamp(1rem, 2vw, 1.2rem);
  color: var(--color-text-muted);
  max-width: 48ch;
  margin: 0 auto 2rem;
  line-height: 1.65;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  justify-content: center;
}

/* ---- Buttons ---- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-sans);
  font-size: 0.9rem;
  font-weight: 600;
  letter-spacing: var(--ls-label);
  text-transform: uppercase;
  padding: 0.75rem 1.75rem;
  border-radius: var(--r-sm);
  border: var(--border);
  cursor: pointer;
  transition: background 0.25s, color 0.25s, box-shadow 0.25s, transform 0.15s;
  white-space: nowrap;
}

.btn:active { transform: scale(0.97); }

.btn-primary {
  background: var(--color-accent);
  color: #fff;
  border-color: var(--color-accent);
}

.btn-primary:hover,
.btn-primary:focus-visible {
  background: var(--color-accent-dark);
  border-color: var(--color-accent-dark);
  box-shadow: 0 4px 20px var(--color-accent-glow);
}

.btn-ghost {
  background: transparent;
  color: var(--color-text);
  border-color: var(--color-border);
}

.btn-ghost:hover,
.btn-ghost:focus-visible {
  background: var(--color-bg-alt);
  border-color: var(--color-text-muted);
}

/* ---- Metrics Strip ---- */
.metrics-strip {
  padding: clamp(2rem, 5vw, 3.5rem) 0;
  border-bottom: var(--border);
  background: var(--color-surface);
}

.metrics-strip .container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(1.25rem, 3vw, 2.5rem);
}

.metric-card {
  text-align: center;
  padding: 1.25rem 1rem;
  border: var(--border);
  border-radius: var(--r-md);
  background: var(--color-bg);
  transition: border-color 0.2s;
}

.metric-card:hover { border-color: var(--color-accent); }

.metric-label {
  display: block;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: var(--ls-label);
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 0.5rem;
}

.metric-value {
  display: block;
  font-family: var(--font-mono);
  font-size: clamp(1.75rem, 4vw, 2.75rem);
  font-weight: 700;
  line-height: 1.1;
}

.metric-unit {
  font-size: 0.6em;
  font-weight: 400;
  color: var(--color-text-muted);
  vertical-align: super;
}

.metric-detail {
  display: block;
  font-size: 0.8rem;
  color: var(--color-text-muted);
  margin-top: 0.5rem;
  line-height: 1.4;
}

/* ---- Features ---- */
.features {
  padding: clamp(3rem, 7vw, 5rem) 0;
  border-bottom: var(--border);
}

.section-heading {
  font-size: clamp(1.4rem, 3.5vw, 2rem);
  font-weight: 700;
  letter-spacing: var(--ls-heading);
  text-align: center;
  text-transform: uppercase;
  margin-bottom: clamp(2rem, 4vw, 3rem);
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(1.25rem, 2.5vw, 2rem);
}

.feature-card {
  background: var(--color-surface);
  border: var(--border);
  border-radius: var(--r-md);
  padding: clamp(1.5rem, 3vw, 2rem);
  transition: border-color 0.25s, box-shadow 0.25s;
}

.feature-card:hover {
  border-color: var(--color-accent);
  box-shadow: 0 2px 16px var(--color-accent-glow);
}

.feature-icon {
  font-size: 1.75rem;
  margin-bottom: 0.75rem;
  line-height: 1;
}

.feature-title {
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: var(--ls-heading);
  text-transform: uppercase;
  margin-bottom: 0.75rem;
}

.feature-desc {
  font-size: 0.925rem;
  color: var(--color-text-muted);
  line-height: 1.65;
}

/* ---- Testimonial ---- */
.testimonial {
  padding: clamp(3rem, 7vw, 5rem) 0;
  border-bottom: var(--border);
  background: var(--color-surface);
}

.testimonial-quote {
  max-width: 56ch;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote > p {
  font-size: clamp(1.05rem, 2.2vw, 1.35rem);
  font-style: italic;
  line-height: 1.7;
  color: var(--color-text);
  padding: 0 0.25rem;
}

.testimonial-quote > p::before {
  content: '\201C';
  display: block;
  font-size: 3rem;
  line-height: 0;
  color: var(--color-accent);
  margin-bottom: 1rem;
  font-style: normal;
  font-weight: 700;
  font-family: var(--font-mono);
}

.testimonial-attribution {
  margin-top: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.testimonial-author {
  font-style: normal;
  font-weight: 700;
  font-size: 1rem;
  letter-spacing: var(--ls-heading);
  text-transform: uppercase;
}

.testimonial-role {
  font-size: 0.8rem;
  color: var(--color-text-muted);
}

/* ---- Footer ---- */
.site-footer {
  padding: clamp(2rem, 4vw, 3rem) 0;
  background: var(--color-bg-alt);
  border-top: var(--border);
  text-align: center;
}

.footer-brand { margin-bottom: 1.25rem; }

.footer-brand .logo-text {
  display: block;
  font-weight: 700;
  font-size: 1.1rem;
  letter-spacing: var(--ls-heading);
  text-transform: uppercase;
  margin-bottom: 0.25rem;
}

.footer-tagline {
  font-size: 0.8rem;
  color: var(--color-text-muted);
}

.footer-social {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1.25rem;
  margin-bottom: 1.5rem;
}

.social-link {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: var(--ls-label);
  text-transform: uppercase;
  color: var(--color-text-muted);
  border-bottom: 1px solid transparent;
  transition: color 0.2s, border-color 0.2s;
  padding-bottom: 2px;
}

.social-link:hover,
.social-link:focus-visible {
  color: var(--color-accent);
  border-bottom-color: var(--color-accent);
}

.footer-copyright {
  font-size: 0.75rem;
  color: var(--color-text-muted);
}

/* ---- Responsive: Tablet ---- */
@media (max-width: 820px) {
  .metrics-strip .container {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .metric-card {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: space-between;
    text-align: left;
    gap: 0.5rem 1rem;
    padding: 1rem 1.25rem;
  }

  .metric-label  { margin-bottom: 0; }
  .metric-value  { font-size: 1.6rem; }
  .metric-detail { flex: 1 1 100%; margin-top: 0.25rem; }

  .feature-grid { grid-template-columns: 1fr 1fr; }
  .site-nav     { gap: 1rem; font-size: 0.75rem; }
}

/* ---- Responsive: Mobile ---- */
@media (max-width: 580px) {
  .site-header .container {
    flex-wrap: wrap;
    height: auto;
    padding-top: 0.75rem;
    padding-bottom: 0.75rem;
    gap: 0.75rem;
    justify-content: center;
  }

  .site-nav {
    flex-wrap: wrap;
    justify-content: center;
    gap: 0.75rem;
  }

  .feature-grid { grid-template-columns: 1fr; }

  .hero-headline { letter-spacing: 0.03em; }

  .hero-actions {
    flex-direction: column;
    width: 100%;
    max-width: 320px;
    margin: 0 auto;
  }

  .hero-actions .btn {
    width: 100%;
    text-align: center;
  }

  .footer-social { gap: 1rem; }
}

/* ---- Accessibility ---- */
:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
}

::selection {
  background: var(--color-accent);
  color: #fff;
}

