/* ---- Testimonial ---- */
.testimonial {
  padding: clamp(3rem, 7vw, 5rem) 0;
  border-bottom: var(--border);
  background: var(--color-surface);
}

.testimonial-quote {
  max-width: 56ch;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote > p {
  font-size: clamp(1.05rem, 2.2vw, 1.35rem);
  font-style: italic;
  line-height: 1.7;
  color: var(--color-text);
  padding: 0 0.25rem;
}

.testimonial-quote > p::before {
  content: '\201C';
  display: block;
  font-size: 3rem;
  line-height: 0;
  color: var(--color-accent);
  margin-bottom: 1rem;
  font-style: normal;
  font-weight: 700;
  font-family: var(--font-mono);
}

.testimonial-attribution {
  margin-top: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.testimonial-author {
  font-style: normal;
  font-weight: 700;
  font-size: 1rem;
  letter-spacing: var(--ls-heading);
  text-transform: uppercase;
}

.testimonial-role {
  font-size: 0.8rem;
  color: var(--color-text-muted);
}

/* ---- Footer ---- */
.site-footer {
  padding: clamp(2rem, 4vw, 3rem) 0;
  background: var(--color-bg-alt);
  border-top: var(--border);
  text-align: center;
}

.footer-brand { margin-bottom: 1.25rem; }

.footer-brand .logo-text {
  display: block;
  font-weight: 700;
  font-size: 1.1rem;
  letter-spacing: var(--ls-heading);
  text-transform: uppercase;
  margin-bottom: 0.25rem;
}

.footer-tagline {
  font-size: 0.8rem;
  color: var(--color-text-muted);
}

.footer-social {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1.25rem;
  margin-bottom: 1.5rem;
}

.social-link {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: var(--ls-label);
  text-transform: uppercase;
  color: var(--color-text-muted);
  border-bottom: 1px solid transparent;
  transition: color 0.2s, border-color 0.2s;
  padding-bottom: 2px;
}

.social-link:hover,
.social-link:focus-visible {
  color: var(--color-accent);
  border-bottom-color: var(--color-accent);
}

.footer-copyright {
  font-size: 0.75rem;
  color: var(--color-text-muted);
}

/* ---- Responsive: Tablet ---- */
@media (max-width: 820px) {
  .metrics-strip .container {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .metric-card {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: space-between;
    text-align: left;
    gap: 0.5rem 1rem;
    padding: 1rem 1.25rem;
  }

  .metric-label  { margin-bottom: 0; }
  .metric-value  { font-size: 1.6rem; }
  .metric-detail { flex: 1 1 100%; margin-top: 0.25rem; }

  .feature-grid { grid-template-columns: 1fr 1fr; }
  .site-nav     { gap: 1rem; font-size: 0.75rem; }
}

/* ---- Responsive: Mobile ---- */
@media (max-width: 580px) {
  .site-header .container {
    flex-wrap: wrap;
    height: auto;
    padding-top: 0.75rem;
    padding-bottom: 0.75rem;
    gap: 0.75rem;
    justify-content: center;
  }

  .site-nav {
    flex-wrap: wrap;
    justify-content: center;
    gap: 0.75rem;
  }

  .feature-grid { grid-template-columns: 1fr; }

  .hero-headline { letter-spacing: 0.03em; }

  .hero-actions {
    flex-direction: column;
    width: 100%;
    max-width: 320px;
    margin: 0 auto;
  }

  .hero-actions .btn {
    width: 100%;
    text-align: center;
  }

  .footer-social { gap: 1rem; }
}

/* ---- Accessibility ---- */
:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
}

::selection {
  background: var(--color-accent);
  color: #fff;
}

