  text-transform: uppercase;
  color: #777;
  font-size: 0.9rem;
  letter-spacing: 0.1em;
  margin-bottom: 0.25rem;
}

.stat-value {
  display: block;
  font-size: 3rem;
  font-weight: 700;
  color: var(--accent);
  line-height: 1.2;
}

.stat-desc {
  display: block;
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-top: 0.25rem;
}

/* ----- Testimonial ----- */
#testimonial {
  padding: 4rem 0;
  background: var(--card-bg);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

blockquote {
  max-width: 700px;
  margin: 0 auto;
  font-style: italic;
  font-size: 1.2rem;
  line-height: 1.7;
  text-align: center;
}

blockquote p {
  color: var(--text);
  margin-bottom: 1rem;
}

cite {
  display: block;
  font-style: normal;
  font-weight: 600;
  color: var(--text-secondary);
  margin-top: 0.5rem;
  letter-spacing: 0.02em;
}

/* ----- Footer ----- */
footer {
  padding: 2rem 0;
  text-align: center;
  border-top: 1px solid var(--border);
  background: var(--bg);
}

.social-links a {
  margin: 0 0.75rem;
  text-decoration: none;
  color: var(--text);
  font-weight: 500;
  transition: color 0.2s;
}

.social-links a:hover {
  color: var(--accent);
}

footer p {
  margin-top: 1rem;
  font-size: 0.9rem;
  color: var(--text-secondary);
}

/* ==========================================
   Responsive Breakpoints
========================================== */

/* Tablets and below (≤ 768px) */
@media (max-width: 768px) {
  header .container {
    flex-direction: column;
    gap: 0.5rem;
  }

  nav a {
    margin-left: 0.75rem;
    margin-right: 0.75rem;
  }

  .cards {
    flex-direction: column;
  }

  .metrics-strip {
    flex-direction: column;
    align-items: center;
    gap: 2rem;
  }

  .stat-value {
    font-size: 2.5rem;
  }

  .hero {
    padding: 2.5rem 0;
  }

  .hero p {
    font-size: 1rem;
  }
}

/* Small phones (≤ 480px, down to 320px) */
@media (max-width: 480px) {
  h1 {
    font-size: 1.7rem;
  }

  h2 {
    font-size: 1.4rem;
  }

  .stat-value {
    font-size: 2rem;
  }

  blockquote {
    font-size: 1rem;
  }

  .card {
    padding: 1.5rem 1rem;
  }
}

