    border: 1.5px solid transparent;
    white-space: nowrap;
}

.btn-primary {
    background-color: var(--accent);
    color: #fff;
    border-color: var(--accent);
}

.btn-primary:hover {
    background-color: #cc1525;
    border-color: #cc1525;
    transform: translateY(-1px);
    box-shadow: 0 4px 14px rgba(232, 25, 42, 0.25);
}

.btn-primary:active {
    transform: translateY(0);
    box-shadow: none;
}

.btn-ghost {
    background-color: transparent;
    color: var(--text);
    border-color: var(--border);
}

.btn-ghost:hover {
    background-color: var(--bg-card);
    border-color: var(--text-dim);
    transform: translateY(-1px);
}

.btn-ghost:active {
    transform: translateY(0);
}

/* ===== Section Titles ===== */
.section-title {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: var(--letter-spacing-heading);
    text-align: center;
    margin-bottom: 2.5rem;
    color: var(--text);
}

/* ===== Metrics Strip ===== */
.metrics-strip {
    padding: 3.5rem 0;
    border-top: 1px solid var(--border-thin);
    border-bottom: 1px solid var(--border-thin);
    background-color: var(--bg-soft);
}

.metrics-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1.5rem;
    margin-bottom: 1.5rem;
}

.metric-card {
    background-color: var(--bg-card);
    border: 1px solid var(--border-light);
    border-radius: var(--radius-lg);
    padding: 1.5rem;
    text-align: center;
    transition: border-color 0.2s ease;
}

.metric-card:hover {
    border-color: var(--border);
}

.metric-label {
    display: block;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--text-dim);
    margin-bottom: 0.75rem;
}

.metric-value {
    display: block;
    font-family: var(--font-mono);
    font-size: 2.5rem;
    font-weight: 700;
    letter-spacing: -0.02em;
    color: var(--text);
    line-height: 1;
    margin-bottom: 0.75rem;
}

.metric-unit {
    font-size: 1.1rem;
    font-weight: 500;
    color: var(--text-dim);
    vertical-align: super;
    margin-left: 0.15rem;
}

.metric-desc {
    font-size: 0.85rem;
    line-height: 1.5;
    color: var(--text-muted);
}

.metrics-footnote {
    text-align: center;
    font-size: 0.8rem;
    color: var(--text-dim);
    font-style: italic;
}

/* ===== Features Section ===== */
.features-section {
    padding: 5rem 0;
}

.features-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1.5rem;
}

.feature-card {
    background-color: var(--bg-card);
    border: 1px solid var(--border-light);
    border-radius: var(--radius-lg);
    padding: 1.75rem;
    transition: border-color 0.2s ease, transform 0.2s ease;
}

.feature-card:hover {
    border-color: var(--border);
    transform: translateY(-2px);
}

.feature-icon {
    color: var(--accent);
    margin-bottom: 1.25rem;
}

.feature-heading {
    font-size: 1.05rem;
    font-weight: 700;
    letter-spacing: var(--letter-spacing-heading);
    margin-bottom: 0.75rem;
    color: var(--text);
}

.feature-card p {
    font-size: 0.9rem;
    line-height: 1.6;
    color: var(--text-muted);
}

/* ===== Testimonial ===== */
.testimonial-section {
    padding: 4rem 0 5rem;
    border-top: 1px solid var(--border-thin);
}

.testimonial {
    max-width: 680px;
    margin: 0 auto;
    text-align: center;
}

.testimonial blockquote {
    position: relative;
    margin-bottom: 1.5rem;
}

.testimonial blockquote::before {
    content: '\201C';
    display: block;
    font-size: 4rem;
    line-height: 1;
    color: var(--accent);
    font-family: Georgia, 'Times New Roman', serif;
    margin-bottom: -0.75rem;
    opacity: 0.6;
}

.testimonial blockquote p {
    font-size: 1.15rem;
    line-height: 1.7;
    color: var(--text);
    font-weight: 500;
    letter-spacing: 0.01em;
}

.testimonial figcaption {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
}

.testimonial-name {
    font-size: 0.95rem;
    font-weight: 700;
    letter-spacing: var(--letter-spacing-heading);
    color: var(--text);
}

.testimonial-role {
    font-size: 0.8rem;
    color: var(--text-dim);
    letter-spacing: 0.02em;
}

/* ===== Footer ===== */
.site-footer {
    border-top: 1px solid var(--border-thin);
    padding: 2.5rem 0;
    background-color: var(--bg-soft);
}

.footer-inner {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 0 1.5rem;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 1.5rem;
}

.footer-brand {
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
}

.footer-logo {
    font-family: var(--font-mono);
    font-weight: 700;
    font-size: 1.05rem;
    letter-spacing: var(--letter-spacing-heading);
    color: var(--text);
}

.footer-tagline {
    font-size: 0.8rem;
    color: var(--text-dim);
}

.footer-social {
    display: flex;
    gap: 1rem;
    align-items: center;
}

.social-link {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: var(--radius);
    color: var(--text-dim);
    transition: color 0.2s ease, background-color 0.2s ease;
    border: 1px solid transparent;
}

.social-link:hover {
    color: var(--text);
    background-color: var(--bg-card);
    border-color: var(--border-light);
}

.footer-bottom {
    width: 100%;
    padding-top: 1.5rem;
    border-top: 1px solid var(--border-thin);
    text-align: center;
    font-size: 0.75rem;
    color: var(--text-dim);
}

/* ===== Responsive Breakpoints ===== */

/* Tablet (below 900px) */
@media (max-width: 900px) {
    .metrics-grid,
    .features-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .hero-headline {
        font-size: clamp(1.6rem, 4.5vw, 2.4rem);
    }
}

/* Mobile (below 640px) */
@media (max-width: 640px) {
    :root {
        --header-height: 52px;
    }

    .section-inner,
    .header-inner,
    .hero-inner,
    .footer-inner {
        padding: 0 1rem;
    }

    .nav-links {
        gap: 1rem;
        font-size: 0.8rem;
    }

    .logo-text {
        display: none;
    }

    .hero {
        padding: 3rem 0 3rem;
    }

    .hero-eyebrow {
        font-size: 0.7rem;
    }

    .hero-headline {
        font-size: 1.5rem;
        letter-spacing: 0.02em;
    }

    .hero-subtitle {
        font-size: 0.95rem;
    }

    .hero-actions {
        flex-direction: column;
        align-items: stretch;
    }

    .btn {
        width: 100%;
        text-align: center;
    }

    .metrics-grid,
    .features-grid {
        grid-template-columns: 1fr;
    }

    .metric-value {
        font-size: 2rem;
    }

    .section-title {
        font-size: 1.25rem;
        margin-bottom: 1.75rem;
    }

    .testimonial blockquote p {
        font-size: 1rem;
    }

    .footer-inner {
        flex-direction: column;
        text-align: center;
    }

    .footer-brand {
        align-items: center;
    }

    .footer-social {
        justify-content: center;
    }
}

/* Small mobile (below 400px) */
@media (max-width: 400px) {
    .hero-headline {
        font-size: 1.35rem;
    }

    .metric-card {
        padding: 1.25rem;
    }

    .metric-value {
        font-size: 1.75rem;
    }

    .feature-card {
        padding: 1.25rem;
    }
}

