/* ===== CSS Variables (Tech-Noir Palette) ===== */
:root {
    --bg: #e4e4e0;
    --bg-soft: #ecece8;
    --bg-card: #f0f0eb;
    --text: #1a1a18;
    --text-muted: #5c5c55;
    --text-dim: #8a8a80;
    --accent: #e8192a;
    --accent-glow: rgba(232, 25, 42, 0.10);
    --accent-light: rgba(232, 25, 42, 0.06);
    --border: #cccbc5;
    --border-light: #d5d4ce;
    --border-thin: #dddcd6;
    --radius: 4px;
    --radius-lg: 6px;
    --font-mono: 'SF Mono', 'Cascadia Code', 'Fira Code', 'JetBrains Mono', 'Consolas', monospace;
    --font-sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    --letter-spacing-heading: 0.03em;
    --max-width: 1100px;
    --header-height: 60px;
}

/* ===== Reset & Base ===== */
*,
*::before,
*::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    font-size: 16px;
    scroll-behavior: smooth;
    -webkit-text-size-adjust: 100%;
}

body {
    font-family: var(--font-sans);
    background-color: var(--bg);
    color: var(--text);
    line-height: 1.6;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

main {
    flex: 1;
}

img,
svg {
    display: block;
    max-width: 100%;
}

a {
    color: inherit;
    text-decoration: none;
}

/* ===== Utility ===== */
.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

.section-inner {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 0 1.5rem;
}

/* ===== Header ===== */
.site-header {
    position: sticky;
    top: 0;
    z-index: 100;
    background-color: rgba(228, 228, 224, 0.92);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--border-thin);
    height: var(--header-height);
}

.header-inner {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 0 1.5rem;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.logo {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-family: var(--font-mono);
    font-weight: 600;
    font-size: 1.25rem;
    letter-spacing: var(--letter-spacing-heading);
    color: var(--text);
    transition: opacity 0.2s ease;
}

.logo:hover {
    opacity: 0.75;
}

.logo-mark {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    border: 2px solid var(--accent);
    border-radius: var(--radius);
    font-size: 0.85rem;
    font-weight: 700;
    color: var(--accent);
    flex-shrink: 0;
}

.nav-links {
    display: flex;
    gap: 1.75rem;
    font-size: 0.9rem;
    font-weight: 500;
    letter-spacing: 0.01em;
    color: var(--text-muted);
}

.nav-links a {
    transition: color 0.2s ease;
    position: relative;
}

.nav-links a:hover,
.nav-links a:focus-visible {
    color: var(--text);
}

.nav-links a::after {
    content: '';
    position: absolute;
    bottom: -4px;
    left: 0;
    width: 0;
    height: 1.5px;
    background-color: var(--accent);
    transition: width 0.25s ease;
}

.nav-links a:hover::after,
.nav-links a:focus-visible::after {
    width: 100%;
}

/* ===== Hero ===== */
.hero {
    padding: 5rem 0 4.5rem;
    text-align: center;
}

.hero-inner {
    max-width: 720px;
    margin: 0 auto;
    padding: 0 1.5rem;
}

.hero-eyebrow {
    font-family: var(--font-mono);
    font-size: 0.8rem;
    font-weight: 500;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--text-dim);
    margin-bottom: 1.25rem;
}

.hero-headline {
    font-size: clamp(2rem, 5vw, 3.2rem);
    font-weight: 700;
    line-height: 1.15;
    letter-spacing: var(--letter-spacing-heading);
    margin-bottom: 1.5rem;
    color: var(--text);
}

.hero-headline .highlight {
    color: var(--accent);
    position: relative;
    white-space: nowrap;
}

.hero-headline .highlight::after {
    content: '';
    position: absolute;
    bottom: 2px;
    left: 0;
    width: 100%;
    height: 6px;
    background-color: var(--accent-glow);
    border-radius: 2px;
    z-index: -1;
}

.hero-subtitle {
    font-size: 1.1rem;
    line-height: 1.7;
    color: var(--text-muted);
    margin-bottom: 2.5rem;
    max-width: 580px;
    margin-left: auto;
    margin-right: auto;
}

.hero-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    justify-content: center;
}

/* ===== Buttons ===== */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0.75rem 1.75rem;
    font-size: 0.9rem;
    font-weight: 600;
    letter-spacing: 0.02em;
    border-radius: var(--radius);
    transition: all 0.2s ease;
    cursor: pointer;
    border: 1.5px solid transparent;
    white-space: nowrap;
}

.btn-primary {
    background-color: var(--accent);
    color: #fff;
    border-color: var(--accent);
}

.btn-primary:hover {
    background-color: #cc1525;
    border-color: #cc1525;
    transform: translateY(-1px);
    box-shadow: 0 4px 14px rgba(232, 25, 42, 0.25);
}

.btn-primary:active {
    transform: translateY(0);
    box-shadow: none;
}

.btn-ghost {
    background-color: transparent;
    color: var(--text);
    border-color: var(--border);
}

.btn-ghost:hover {
    background-color: var(--bg-card);
    border-color: var(--text-dim);
    transform: translateY(-1px);
}

.btn-ghost:active {
    transform: translateY(0);
}

/* ===== Section Titles ===== */
.section-title {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: var(--letter-spacing-heading);
    text-align: center;
    margin-bottom: 2.5rem;
    color: var(--text);
}

/* ===== Metrics Strip ===== */
.metrics-strip {
    padding: 3.5rem 0;
    border-top: 1px solid var(--border-thin);
    border-bottom: 1px solid var(--border-thin);
    background-color: var(--bg-soft);
}

.metrics-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1.5rem;
    margin-bottom: 1.5rem;
}

.metric-card {
    background-color: var(--bg-card);
    border: 1px solid var(--border-light);
    border-radius: var(--radius-lg);
    padding: 1.5rem;
    text-align: center;
    transition: border-color 0.2s ease;
}

.metric-card:hover {
    border-color: var(--border);
}

.metric-label {
    display: block;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--text-dim);
    margin-bottom: 0.75rem;
}

.metric-value {
    display: block;
    font-family: var(--font-mono);
    font-size: 2.5rem;
    font-weight: 700;
    letter-spacing: -0.02em;
    color: var(--text);
    line-height: 1;
    margin-bottom: 0.75rem;
}

.metric-unit {
    font-size: 1.1rem;
    font-weight: 500;
    color: var(--text-dim);
    vertical-align: super;
    margin-left: 0.15rem;
}

.metric-desc {
    font-size: 0.85rem;
    line-height: 1.5;
    color: var(--text-muted);
}

.metrics-footnote {
    text-align: center;
    font-size: 0.8rem;
    color: var(--text-dim);
    font-style: italic;
}

/* ===== Features Section ===== */
.features-section {
    padding: 5rem 0;
}

.features-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1.5rem;
}

.feature-card {
    background-color: var(--bg-card);
    border: 1px solid var(--border-light);
    border-radius: var(--radius-lg);
    padding: 1.75rem;
    transition: border-color 0.2s ease, transform 0.2s ease;
}

.feature-card:hover {
    border-color: var(--border);
    transform: translateY(-2px);
}

.feature-icon {
    color: var(--accent);
    margin-bottom: 1.25rem;
}

.feature-heading {
    font-size: 1.05rem;
    font-weight: 700;
    letter-spacing: var(--letter-spacing-heading);
    margin-bottom: 0.75rem;
    color: var(--text);
}

.feature-card p {
    font-size: 0.9rem;
    line-height: 1.6;
    color: var(--text-muted);
}

/* ===== Testimonial ===== */
.testimonial-section {
    padding: 4rem 0 5rem;
    border-top: 1px solid var(--border-thin);
}

.testimonial {
    max-width: 680px;
    margin: 0 auto;
    text-align: center;
}

.testimonial blockquote {
    position: relative;
    margin-bottom: 1.5rem;
}

.testimonial blockquote::before {
    content: '\201C';
    display: block;
    font-size: 4rem;
    line-height: 1;
    color: var(--accent);
    font-family: Georgia, 'Times New Roman', serif;
    margin-bottom: -0.75rem;
    opacity: 0.6;
}

.testimonial blockquote p {
    font-size: 1.15rem;
    line-height: 1.7;
    color: var(--text);
    font-weight: 500;
    letter-spacing: 0.01em;
}

.testimonial figcaption {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
}

.testimonial-name {
    font-size: 0.95rem;
    font-weight: 700;
    letter-spacing: var(--letter-spacing-heading);
    color: var(--text);
}

.testimonial-role {
    font-size: 0.8rem;
    color: var(--text-dim);
    letter-spacing: 0.02em;
}

/* ===== Footer ===== */
.site-footer {
    border-top: 1px solid var(--border-thin);
    padding: 2.5rem 0;
    background-color: var(--bg-soft);
}

.footer-inner {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 0 1.5rem;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 1.5rem;
}

.footer-brand {
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
}

.footer-logo {
    font-family: var(--font-mono);
    font-weight: 700;
    font-size: 1.05rem;
    letter-spacing: var(--letter-spacing-heading);
    color: var(--text);
}

.footer-tagline {
    font-size: 0.8rem;
    color: var(--text-dim);
}

.footer-social {
    display: flex;
    gap: 1rem;
    align-items: center;
}

.social-link {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: var(--radius);
    color: var(--text-dim);
    transition: color 0.2s ease, background-color 0.2s ease;
    border: 1px solid transparent;
}

.social-link:hover {
    color: var(--text);
    background-color: var(--bg-card);
    border-color: var(--border-light);
}

.footer-bottom {
    width: 100%;
    padding-top: 1.5rem;
    border-top: 1px solid var(--border-thin);
    text-align: center;
    font-size: 0.75rem;
    color: var(--text-dim);
}

/* ===== Responsive Breakpoints ===== */

/* Tablet (below 900px) */
@media (max-width: 900px) {
    .metrics-grid,
    .features-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .hero-headline {
        font-size: clamp(1.6rem, 4.5vw, 2.4rem);
    }
}

/* Mobile (below 640px) */
@media (max-width: 640px) {
    :root {
        --header-height: 52px;
    }

    .section-inner,
    .header-inner,
    .hero-inner,
    .footer-inner {
        padding: 0 1rem;
    }

    .nav-links {
        gap: 1rem;
        font-size: 0.8rem;
    }

    .logo-text {
        display: none;
    }

    .hero {
        padding: 3rem 0 3rem;
    }

    .hero-eyebrow {
        font-size: 0.7rem;
    }

    .hero-headline {
        font-size: 1.5rem;
        letter-spacing: 0.02em;
    }

    .hero-subtitle {
        font-size: 0.95rem;
    }

    .hero-actions {
        flex-direction: column;
        align-items: stretch;
    }

    .btn {
        width: 100%;
        text-align: center;
    }

    .metrics-grid,
    .features-grid {
        grid-template-columns: 1fr;
    }

    .metric-value {
        font-size: 2rem;
    }

    .section-title {
        font-size: 1.25rem;
        margin-bottom: 1.75rem;
    }

    .testimonial blockquote p {
        font-size: 1rem;
    }

    .footer-inner {
        flex-direction: column;
        text-align: center;
    }

    .footer-brand {
        align-items: center;
    }

    .footer-social {
        justify-content: center;
    }
}

/* Small mobile (below 400px) */
@media (max-width: 400px) {
    .hero-headline {
        font-size: 1.35rem;
    }

    .metric-card {
        padding: 1.25rem;
    }

    .metric-value {
        font-size: 1.75rem;
    }

    .feature-card {
        padding: 1.25rem;
    }
}

args.content:
:root {
  --bg: #e4e4e0;
  --accent: #e8192a;
  --text: #1a1a1a;
  --text-light: #4a4a4a;
  --border-color: #babab6;
  --card-bg: #f4f4f0;
  --radius: 4px;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 2rem;
  --spacing-lg: 3rem;
  --spacing-xl: 5rem;
  --font-mono: 'Courier New', Courier, monospace;
  --letter-spacing-heading: 0.12em;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
  font-size: 16px;
  min-width: 320px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-sm);
}

/* Typography */
h1, h2, h3 {
  letter-spacing: var(--letter-spacing-heading);
  font-weight: 700;
  line-height: 1.2;
}

h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  text-transform: uppercase;
}

h2 {
  font-size: clamp(1.5rem, 3vw, 2rem);
  margin-bottom: var(--spacing-md);
  border-bottom: 1px solid var(--border-color);
  padding-bottom: var(--spacing-xs);
  display: inline-block;
}

h3 {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-xs);
}

p, .subhead {
  max-width: 65ch;
}

/* Header */
header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--spacing-md) 0;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: var(--spacing-lg);
}

.logo {
  font-weight: 900;
  font-size: 1.8rem;
  letter-spacing: var(--letter-spacing-heading);
  text-transform: lowercase;
  color: var(--accent);
}

nav a {
  color: var(--text);
  text-decoration: none;
  margin-left: var(--spacing-sm);
  font-weight: 500;
  transition: color 0.2s;
  border-bottom: 1px solid transparent;
}

nav a:hover {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

/* Hero */
.hero {
  padding: var(--spacing-xl) 0;
  text-align: center;
  border-bottom: 1px solid var(--border-color);
}

.hero h1 {
  margin-bottom: var(--spacing-sm);
}

.subhead {
  font-size: 1.2rem;
  color: var(--text-light);
  margin: 0 auto var(--spacing-md);
}

.cta {
  display: inline-block;
  background-color: var(--accent);
  color: #fff;
  padding: 0.75rem 2rem;
  text-decoration: none;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  border-radius: var(--radius);
  transition: background-color 0.2s, color 0.2s;
  border: 1px solid var(--accent);
}

.cta:hover {
  background-color: transparent;
  color: var(--accent);
}

/* Features */
.features {
  padding: var(--spacing-xl) 0;
}

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-md);
}

.card {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  padding: var(--spacing-md);
  border-radius: var(--radius);
  transition: transform 0.2s, box-shadow 0.2s;
}

.card:hover {
  transform: translateY(-3px);
  box-shadow: 0 6px 12px rgba(0,0,0,0.05);
}

.card-icon {
  font-size: 2.5rem;
  margin-bottom: var(--spacing-xs);
}

.card h3 {
  margin-top: 0;
}

.card p {
  color: var(--text-light);
  font-size: 0.95rem;
}

/* Metrics Strip */
.metrics-strip {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  padding: var(--spacing-lg);
  text-align: center;
  margin-bottom: var(--spacing-xl);
  border-left: none;
  border-right: none;
}

.strip-heading {
  font-size: 1.2rem;
  margin-bottom: var(--spacing-md);
  letter-spacing: 0.05em;
  border-bottom: none;
}

.stats {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: var(--spacing-lg);
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 120px;
}

.stat .label {
  font-family: var(--font-mono);
  font-size: 0.9rem;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.stat .value {
  font-family: var(--font-mono);
  font-size: 2.5rem;
  font-weight: 700;
  margin-top: 0.2rem;
  color: var(--text);
}

.strip-note {
  margin-top: var(--spacing-sm);
  font-size: 0.85rem;
  color: var(--text-light);
}

/* Testimonial */
.testimonial {
