  padding: 80px 0;
  text-align: center;
}

.features h2 {
  margin-bottom: 3rem;
}

.cards {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
  justify-content: center;
}

.card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 2.25rem 2rem;
  flex: 1 1 280px;
  max-width: 350px;
  box-shadow: var(--shadow);
  transition: transform 0.25s, box-shadow 0.25s;
  text-align: left;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
}

.card-icon {
  font-size: 2rem;
  margin-bottom: 1rem;
  display: block;
}

.card h3 {
  margin-bottom: 0.6rem;
  color: var(--dark);
}

.card p {
  color: var(--text-muted);
  font-size: 0.95rem;
  line-height: 1.6;
}

/* Metrics (monospace strip) */
.metrics {
  background-color: var(--metrics-bg);
  color: #ffffff;
  padding: 80px 0;
  text-align: center;
}

.metrics h2 {
  color: #ffffff;
  letter-spacing: 0.1em;
}

.metrics-subtitle {
  color: rgba(255, 255, 255, 0.75);
  margin: 0.5rem 0 2.5rem;
  font-size: 1.05rem;
}

.metrics-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 2.5rem;
}

.metric-item {
  min-width: 160px;
}

.metric-label {
  display: block;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 0.8rem;
  color: rgba(255, 255, 255, 0.85);
  margin-bottom: 0.2rem;
}

.metric-value {
  display: block;
  font-family: "Courier New", Courier, monospace;
  font-size: 2.25rem;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: -0.02em;
}

/* Testimonial */
.testimonial {
  background: #f5f5f3;
  padding: 80px 0;
}

blockquote {
  max-width: 700px;
  margin: 0 auto;
  font-style: italic;
  font-size: 1.3rem;
  line-height: 1.45;
  color: #2b2b2b;
  position: relative;
}

blockquote::before {
  content: "“";
  font-size: 3.5rem;
  color: var(--accent);
  position: absolute;
  left: -1.2rem;
  top: -1.2rem;
  line-height: 1;
  opacity: 0.3;
}

blockquote p {
  margin-bottom: 1.2rem;
}

blockquote footer {
  font-size: 0.9rem;
  color: var(--text-muted);
  font-style: normal;
}

cite {
  font-style: normal;
}

/* Footer */
footer {
  background: var(--dark);
  color: #bbbbbb;
  padding: 40px 0;
  text-align: center;
  font-size: 0.95rem;
}

footer .container {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
}

.social-links {
  display: flex;
  gap: 2rem;
}

.social-links a {
  color: #bbbbbb;
  text-decoration: none;
  letter-spacing: 0.05em;
  font-weight: 500;
  transition: color 0.2s;
}

.social-links a:hover {
  color: var(--accent);
}

/* Responsive — 320px to 1200px */
@media screen and (max-width: 768px) {
  header .container {
    flex-direction: column;
    gap: 10px;
  }

  .hero {
    padding: 60px 0 50px;
  }

  .cards {
    gap: 1.5rem;
  }

  .card {
    max-width: 100%;
  }

  .metrics-grid {
    gap: 1.5rem;
  }

  .metric-value {
    font-size: 1.9rem;
  }

  blockquote {
    font-size: 1.1rem;
  }
}

@media screen and (max-width: 480px) {
  .container {
    padding: 0 16px;
  }

  .hero h1 {
    font-size: 1.8rem;
  }

  .hero p {
    font-size: 1rem;
  }

  .features h2 {
    margin-bottom: 2rem;
  }
}

