/* ===== DESIGN TOKENS ===== */
:root {
    --bg: #e4e4e0;
    --accent: #e8192a;
    --text-primary: #1a1a1a;
    --text-secondary: #555;
    --border: #cfcfc6;
    --card-bg: #ffffff;
    --max-width: 1200px;
    --letter-spacing-wide: 0.12em;
    --font-mono: 'Courier New', Courier, monospace;
}

/* ===== RESET & BASE ===== */
*,
*::before,
*::after {
    box-sizing: border-box;
}

body {
    margin: 0;
    font-family: system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    background: var(--bg);
    color: var(--text-primary);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
}

a {
    color: var(--accent);
    text-decoration: none;
    transition: color 0.2s;
}

a:hover {
    color: #b51420;
}

img {
    max-width: 100%;
    display: block;
}

.container {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 0 1.5rem;
}

/* ===== TYPOGRAPHY ===== */
h1, h2, h3, h4, h5, h6 {
    letter-spacing: var(--letter-spacing-wide);
    text-transform: uppercase;
    font-weight: 700;
    line-height: 1.2;
}

/* ===== HEADER ===== */
.header {
    background: var(--bg);
    border-bottom: 1px solid var(--border);
    padding: 1.25rem 0;
}

.header .container {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
}

.logo {
    font-size: 1.2rem;
    font-weight: 800;
    letter-spacing: 0.2em;
    color: var(--text-primary);
}

.nav {
    display: flex;
    gap: 1.5rem;
}

.nav a {
    font-size: 0.85rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--text-primary);
    font-weight: 600;
    padding: 0.25rem 0;
    border-bottom: 2px solid transparent;
    transition: border-color 0.2s, color 0.2s;
}

.nav a:hover {
    border-bottom-color: var(--accent);
    color: var(--accent);
}

/* ===== HERO ===== */
.hero {
    text-align: center;
    padding: 5rem 0 4rem;
}

.hero-headline {
    font-size: clamp(2.2rem, 8vw, 4rem);
    margin: 0 auto 1.5rem;
    max-width: 800px;
    color: var(--text-primary);
}

.hero-subhead {
    font-size: 1.2rem;
    color: var(--text-secondary);
    max-width: 600px;
    margin: 0 auto 2.5rem;
    line-height: 1.7;
}

.cta-button {
    display: inline-block;
    background: var(--accent);
    color: #fff;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
    padding: 0.9em 2.4em;
    border-radius: 2px;
    transition: background 0.2s, transform 0.2s;
}

.cta-button:hover {
    background: #c21422;
    color: #fff;
    transform: translateY(-1px);
}

/* ===== FEATURES ===== */
.features {
    padding: 4rem 0;
}

.section-title {
    text-align: center;
    font-size: 2rem;
    margin-bottom: 3rem;
    color: var(--text-primary);
}

.feature-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 2rem;
}

.card {
    background: var(--card-bg);
    border: 1px solid var(--border);
    padding: 2rem 1.5rem;
    text-align: center;
    border-radius: 4px;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.04);
    transition: transform 0.2s, box-shadow 0.2s;
}

.card:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.08);
}

.card-icon {
    font-size: 2.5rem;
    color: var(--accent);
    margin-bottom: 1rem;
    line-height: 1;
}

.card-title {
    font-size: 1.1rem;
    margin-bottom: 0.75rem;
    color: var(--text-primary);
}

.card-text {
    font-size: 0.95rem;
    color: var(--text-secondary);
    line-height: 1.6;
}

/* ===== METRICS STRIP ===== */
.metrics-strip {
    background: var(--accent);
    color: #fff;
    padding: 3rem 0;
    text-align: center;
}

.metrics-strip .container {
    display: flex;
    justify-content: center;
    align-items: baseline;
    gap: 5rem;
    flex-wrap: wrap;
}

.metric {
    text-align: center;
    min-width: 150px;
}

.metric-value {
    font-family: var(--font-mono);
    font-size: 3rem;
    font-weight: 700;
    line-height: 1.1;
    display: block;
}

.metric-label {
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    opacity: 0.9;
    margin-top: 0.5rem;
    display: block;
}

/* ===== TESTIMONIAL ===== */
.testimonial {
    padding: 4rem 0;
    border-top: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
}

.testimonial blockquote {
    max-width: 700px;
    margin: 0 auto;
    font-style: italic;
    font-size: 1.2rem;
    line-height: 1.8;
    color: var(--text-primary);
    border-left: 3px solid var(--accent);
    padding-left: 2rem;
    text-align: left;
}

.testimonial blockquote p {
    margin: 0;
}

.testimonial cite {
    display: block;
    margin-top: 1.5rem;
    font-style: normal;
    font-size: 0.9rem;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

/* ===== FOOTER ===== */
.footer {
    background: #1a1a1a;
    color: #aaa;
    padding: 2.5rem 0;
    text-align: center;
}

.social-links {
    margin-bottom: 1rem;
}

.social-links a {
    margin: 0 1rem;
    color: #aaa;
    font-weight: 600;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    font-size: 0.9rem;
}

.social-links a:hover {
    color: var(--accent);
}

.copyright {
    font-size: 0.85rem;
    opacity: 0.7;
    margin: 0;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 768px) {
    .header .container {
        flex-direction: column;
        align-items: flex-start;
    }

    .nav {
        flex-wrap: wrap;
        gap: 1rem;
    }

    .hero {
        padding: 3rem 0 2.5rem;
    }

    .metrics-strip .container {
        gap: 2.5rem;
    }

    .metric-value {
        font-size: 2.4rem;
    }

    .testimonial blockquote {
        font-size: 1.05rem;
        padding-left: 1.5rem;
    }
}

@media (max-width: 480px) {
    .hero-headline {
        font-size: 1.8rem;
    }

    .hero-subhead {
        font-size: 1rem;
    }

    .feature-cards {
        grid-template-columns: 1fr;
    }

    .metrics-strip .container {
        flex-direction: column;
        align-items: center;
        gap: 2rem;
    }

    .metric-value {
        font-size: 2.2rem;
    }
}

