/* ===== DESIGN TOKENS ===== */
:root {
    --bg: #e4e4e0;
    --accent: #e8192a;
    --text-primary: #1a1a1a;
    --text-secondary: #555;
    --border: #cfcfc6;
    --card-bg: #ffffff;
    --max-width: 1200px;
    --letter-spacing-wide: 0.12em;
    --font-mono: 'Courier New', Courier, monospace;
}

/* ===== RESET & BASE ===== */
*,
*::before,
*::after {
    box-sizing: border-box;
}

body {
    margin: 0;
    font-family: system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    background: var(--bg);
    color: var(--text-primary);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
}

a {
    color: var(--accent);
    text-decoration: none;
    transition: color 0.2s;
}

a:hover {
    color: #b51420;
}

img {
    max-width: 100%;
    display: block;
}

.container {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 0 1.5rem;
}

/* ===== TYPOGRAPHY ===== */
h1, h2, h3, h4, h5, h6 {
    letter-spacing: var(--letter-spacing-wide);
    text-transform: uppercase;
    font-weight: 700;
    line-height: 1.2;
}

/* ===== HEADER ===== */
.header {
    background: var(--bg);
    border-bottom: 1px solid var(--border);
    padding: 1.25rem 0;
}

.header .container {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
}

.logo {
    font-size: 1.2rem;
    font-weight: 800;
    letter-spacing: 0.2em;
    color: var(--text-primary);
}

.nav {
    display: flex;
    gap: 1.5rem;
}

.nav a {
    font-size: 0.85rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--text-primary);
    font-weight: 600;
    padding: 0.25rem 0;
    border-bottom: 2px solid transparent;
    transition: border-color 0.2s, color 0.2s;
}

.nav a:hover {
    border-bottom-color: var(--accent);
    color: var(--accent);
}

/* ===== HERO ===== */
.hero {
    text-align: center;
    padding: 5rem 0 4rem;
}

.hero-headline {
    font-size: clamp(2.2rem, 8vw, 4rem);
    margin: 0 auto 1.5rem;
    max-width: 800px;
    color: var(--text-primary);
}

.hero-subhead {
    font-size: 1.2rem;
    color: var(--text-secondary);
    max-width: 600px;
    margin: 0 auto 2.5rem;
    line-height: 1.7;
}

.cta-button {
    display: inline-block;
    background: var(--accent);
    color: #fff;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
    padding: 0.9em 2.4em;
    border-radius: 2px;
    transition: background 0.2s, transform 0.2s;
}

.cta-button:hover {
    background: #c21422;
    color: #fff;
    transform: translateY(-1px);
}

/* ===== FEATURES ===== */
.features {
    padding: 4rem 0;
}

.section-title {
    text-align: center;
    font-size: 2rem;
    margin-bottom: 3rem;
    color: var(--text-primary);
}

.feature-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 2rem;
}

.card {
    background: var(--card-bg);
    border: 1px solid var(--border);
    padding: 2rem 1.5rem;
    text-align: center;
    border-radius: 4px;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.04);
    transition: transform 0.2s, box-shadow 0.2s;
}

.card:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.08);
}

.card-icon {
    font-size: 2.5rem;
    color: var(--accent);
    margin-bottom: 1rem;
    line-height: 1;
}

.card-title {
    font-size: 1.1rem;
    margin-bottom: 0.75rem;
    color: var(--text-primary);
}

.card-text {
    font-size: 0.95rem;
    color: var(--text-secondary);
    line-height: 1.6;
}

/* ===== METRICS STRIP ===== */
.metrics-strip {
    background: var(--accent);
    color: #fff;
    padding: 3rem 0;
    text-align: center;
}

.metrics-strip .container {
    display: flex;
    justify-content: center;
    align-items: baseline;
    gap: 5rem;
    flex-wrap: wrap;
}

.metric {
    text-align: center;
    min-width: 150px;
}

.metric-value {
    font-family: var(--font-mono);
    font-size: 3rem;
    font-weight: 700;
    line-height: 1.1;
    display: block;
}

.metric-label {
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    opacity: 0.9;
    margin-top: 0.5rem;
    display: block;
}

/* ===== TESTIMONIAL ===== */
.testimonial {
    padding: 4rem 0;
    border-top: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
}

.testimonial blockquote {
    max-width: 700px;
    margin: 0 auto;
    font-style: italic;
    font-size: 1.2rem;
    line-height: 1.8;
    color: var(--text-primary);
    border-left: 3px solid var(--accent);
    padding-left: 2rem;
    text-align: left;
}

.testimonial blockquote p {
    margin: 0;
}

.testimonial cite {
    display: block;
    margin-top: 1.5rem;
    font-style: normal;
    font-size: 0.9rem;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

/* ===== FOOTER ===== */
.footer {
    background: #1a1a1a;
    color: #aaa;
    padding: 2.5rem 0;
    text-align: center;
}

.social-links {
    margin-bottom: 1rem;
}

.social-links a {
    margin: 0 1rem;
    color: #aaa;
    font-weight: 600;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    font-size: 0.9rem;
}

.social-links a:hover {
    color: var(--accent);
}

.copyright {
    font-size: 0.85rem;
    opacity: 0.7;
    margin: 0;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 768px) {
    .header .container {
        flex-direction: column;
        align-items: flex-start;
    }

    .nav {
        flex-wrap: wrap;
        gap: 1rem;
    }

    .hero {
        padding: 3rem 0 2.5rem;
    }

    .metrics-strip .container {
        gap: 2.5rem;
    }

    .metric-value {
        font-size: 2.4rem;
    }

    .testimonial blockquote {
        font-size: 1.05rem;
        padding-left: 1.5rem;
    }
}

@media (max-width: 480px) {
    .hero-headline {
        font-size: 1.8rem;
    }

    .hero-subhead {
        font-size: 1rem;
    }

    .feature-cards {
        grid-template-columns: 1fr;
    }

    .metrics-strip .container {
        flex-direction: column;
        align-items: center;
        gap: 2rem;
    }

    .metric-value {
        font-size: 2.2rem;
    }
}

args.content:
/* ===== CSS VARIABLES (Tech‑Noir Palette) ===== */
:root {
  --color-bg: #e4e4e0;          /* light gray background */
  --color-surface: #f8f8f6;     /* slightly lighter for cards */
  --color-text: #1a1a1a;
  --color-muted: #555;
  --color-accent: #e8192a;      /* red accent */
  --color-accent-hover: #c01024;
  --color-border: #d4d4d0;      /* thin border */
  --font-mono: 'Courier New', Courier, monospace;
  --font-sans: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif;
  --letter-spacing-heading: 0.12em;
  --max-width: 1200px;
  --radius: 4px;
  --transition: 0.2s ease;
}

/* ===== RESET & BASE ===== */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

/* ===== CONTAINER ===== */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* ===== TYPOGRAPHY ===== */
h1, h2, h3 {
  letter-spacing: var(--letter-spacing-heading);
  text-transform: uppercase;
  font-weight: 600;
  line-height: 1.2;
}

h1 {
  font-size: clamp(2rem, 5vw, 3.4rem);
  margin-bottom: 1rem;
}

h2 {
  font-size: clamp(1.4rem, 3vw, 2rem);
  margin-bottom: 2rem;
}

h3 {
  font-size: 1.2rem;
  margin-bottom: 0.5rem;
}

p {
  margin-bottom: 1rem;
}

a {
  color: var(--color-accent);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover,
a:focus-visible {
  color: var(--color-accent-hover);
  outline: none;
}

/* ===== HEADER ===== */
.site-header {
  border-bottom: 1px solid var(--color-border);
  padding: 1rem 0;
  background: var(--color-surface);
}

.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.8rem;
}

.logo {
  font-family: var(--font-mono);
  font-size: 1.25rem;
  font-weight: 600;
  letter-spacing: var(--letter-spacing-heading);
  color: var(--color-text);
  display: flex;
  align-items: center;
  gap: 0.4rem;
  text-decoration: none;
}

.logo-mark {
  font-size: 1.4rem;
  color: var(--color-accent);
}

.site-nav {
  display: flex;
  gap: 1.5rem;
}

.site-nav a {
  font-size: 0.95rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

/* ===== HERO ===== */
.hero {
  padding: 5rem 0 3rem;
  text-align: center;
}

.hero-subtitle {
  font-size: 1.1rem;
  max-width: 720px;
  margin: 0 auto 2rem;
  color: var(--color-muted);
}

.hero-actions {
  display: flex;
  justify-content: center;
  gap: 1rem;
  flex-wrap: wrap;
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-block;
  padding: 0.75rem 1.8rem;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  border: 1px solid transparent;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background var(--transition), color var(--transition), border-color var(--transition);
}

.btn-primary {
  background: var(--color-accent);
  color: #fff;
  border-color: var(--color-accent);
}

.btn-primary:hover,
.btn-primary:focus-visible {
  background: var(--color-accent-hover);
  border-color: var(--color-accent-hover);
  color: #fff;
}

.btn-ghost {
  background: transparent;
  border: 1px solid var(--color-border);
  color: var(--color-text);
}

.btn-ghost:hover,
.btn-ghost:focus-visible {
  background: var(--color-surface);
  border-color: var(--color-accent);
  color: var(--color-accent);
}

/* ===== METRICS STRIP (id="metrics") ===== */
.metrics-strip {
  padding: 3rem 0;
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

.metrics-label {
  text-align: center;
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--color-muted);
  margin-bottom: 2rem;
}

.metrics-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 1.5rem;
  text-align: center;
}

.metric-card {
  border: 1px solid var(--color-border);
  padding: 1.5rem 1rem;
  background: var(--color-bg);
  border-radius: var(--radius);
  transition: border-color var(--transition);
}

.metric-card:hover {
  border-color: var(--color-accent);
}

.metric-name {
  display: block;
  font-family: var(--font-mono);
  font-size: 1rem;
  letter-spacing: 0.05em;
  text-transform: lowercase;
  color: var(--color-muted);
  margin-bottom: 0.5rem;
}

.metric-value {
  display: block;
  font-family: var(--font-mono);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-text);
  line-height: 1.1;
}

.metric-unit {
  font-size: 1.2rem;
  font-weight: 400;
  color: var(--color-accent);
  margin-left: 0.15rem;
}

.metric-desc {
  display: block;
  font-size: 0.85rem;
  color: var(--color-muted);
  margin-top: 0.3rem;
}

/* ===== FEATURES ===== */
.features {
  padding: 5rem 0;
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 2rem;
}

.feature-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  padding: 2rem;
  border-radius: var(--radius);
  transition: border-color var(--transition), box-shadow var(--transition);
}

.feature-card:hover {
  border-color: var(--color-accent);
  box-shadow: 0 2px 8px rgba(0,0,0,0.04);
}

.feature-icon {
  font-size: 2rem;
  color: var(--color-accent);
  margin-bottom: 1rem;
  line-height: 1;
}

.feature-card h3 {
  margin-bottom: 0.8rem;
}

.feature-card p {
  color: var(--color-muted);
  font-size: 0.95rem;
}

/* ===== TESTIMONIAL ===== */
.testimonial {
  padding: 4rem 0;
  border-top: 1px solid var(--color-border);
}

.testimonial-quote {
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote blockquote {
  font-size: 1.25rem;
  font-style: italic;
  color: var(--color-text);
  position: relative;
  padding: 0 1rem;
}

.testimonial-quote blockquote::before {
  content: open-quote;
  font-size: 4rem;
  color: var(--color-accent);
  line-height: 0.2;
  vertical-align: -0.4em;
  font-style: normal;
  font-family: var(--font-mono);
}

.testimonial-quote figcaption {
  margin-top: 1.5rem;
  font-size: 0.9rem;
  color: var(--color-muted);
}

.testimonial-quote figcaption strong {
  display: block;
  color: var(--color-text);
  font-size: 1rem;
  letter-spacing: 0.04em;
}

/* ===== CTA ===== */
.cta {
  padding: 4rem 0;
  text-align: center;
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
}

.cta p {
  color: var(--color-muted);
  margin-bottom: 2rem;
}

/* ===== FOOTER ===== */
.site-footer {
  border-top: 1px solid var(--color-border);
  padding: 2rem 0;
  background: var(--color-surface);
}

.site-footer .container {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.footer-brand {
  font-family: var(--font-mono);
  font-weight: 600;
  letter-spacing: var(--letter-spacing-heading);
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

.footer-social {
  display: flex;
  gap: 1.5rem;
}

.footer-social a {
  font-size: 0.9rem;
  font-weight: 500;
}

.footer-meta {
  font-size: 0.85rem;
  color: var(--color-muted);
  text-align: center;
  width: 100%;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 600px) {
  .hero {
    padding: 3rem 0 2rem;
  }

  .hero-subtitle {
    font-size: 1rem;
  }

  .metrics-grid {
    grid-template-columns: 1fr;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .site-header .container,
  .site-footer .container {
    flex-direction: column;
    text-align: center;
  }

  .site-nav,
  .footer-social {
    justify-content: center;
    gap: 1rem;
  }
}

