/* ============================================================
   Murmur — Tech-Noir Palette & Variables
   ============================================================ */
:root {
  --color-bg:        #e4e4e0;
  --color-surface:   #ffffff;
  --color-text:      #1a1a1a;
  --color-muted:     #5c5c55;
  --color-accent:    #e8192a;
  --color-accent-dim: rgba(232, 25, 42, 0.08);
  --color-border:    #cccccc;
  --color-border-light: #d9d9d4;
  --color-dark:      #1a1a1a;

  --font-sans:  -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --font-mono:  "SF Mono", "Fira Code", "Cascadia Code", "Courier New", monospace;

  --letter-spacing-heading: 0.10em;
  --letter-spacing-label:   0.14em;

  --border-thin: 1px solid var(--color-border);

  --max-width: 1200px;
  --gutter:    2rem;
}

/* ============================================================
   Reset & Base
   ============================================================ */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-sans);
  line-height: 1.65;
  min-height: 100vh;
}

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--gutter);
}

/* ============================================================
   Screen Reader Only
   ============================================================ */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ============================================================
   Hero
   ============================================================ */
.hero {
  padding: 7rem 0 5rem;
  text-align: center;
}

.hero-headline {
  font-size: clamp(2.4rem, 6vw, 4rem);
  font-weight: 700;
  letter-spacing: var(--letter-spacing-heading);
  text-transform: lowercase;
  color: var(--color-dark);
  line-height: 1.1;
  margin-bottom: 0.75rem;
}

.hero-dot {
  color: var(--color-accent);
}

.hero-subhead {
  font-size: clamp(1rem, 2.5vw, 1.35rem);
  font-weight: 400;
  letter-spacing: 0.04em;
  color: var(--color-muted);
  margin-bottom: 1.25rem;
}

.hero-desc {
  font-size: clamp(0.9rem, 1.8vw, 1.05rem);
  max-width: 620px;
  margin: 0 auto 2.5rem;
  color: var(--color-muted);
  line-height: 1.7;
}

/* Primary button */
.btn-primary {
  display: inline-block;
  padding: 0.75rem 2.2rem;
  font-family: var(--font-sans);
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-decoration: none;
  color: var(--color-accent);
  background: transparent;
  border: var(--border-thin);
  border-color: var(--color-accent);
  transition: background 0.2s ease, color 0.2s ease, box-shadow 0.2s ease;
  cursor: pointer;
}

.btn-primary:hover,
.btn-primary:focus-visible {
  background: var(--color-accent);
  color: #ffffff;
  box-shadow: 0 0 0 4px var(--color-accent-dim);
  outline: none;
}

/* ============================================================
   Features Section
   ============================================================ */
.features {
  padding: 4rem 0 5rem;
}

.features .container {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.75rem;
}

.feature-card {
  background: var(--color-surface);
  border: var(--border-thin);
  border-color: var(--color-border-light);
  padding: 2.5rem 2rem 2rem;
  text-align: center;
  transition: border-color 0.25s ease, box-shadow 0.25s ease, transform 0.25s ease;
}

.feature-card:hover {
  border-color: var(--color-accent);
  box-shadow: 0 6px 24px var(--color-accent-dim);
  transform: translateY(-3px);
}

.feature-icon {
  display: block;
  width: 52px;
  height: 52px;
  margin: 0 auto 1.5rem;
  color: var(--color-accent);
}

.feature-icon svg {
  width: 100%;
  height: 100%;
  display: block;
}

.feature-card h3 {
  font-size: 1.05rem;
  font-weight: 600;
  letter-spacing: var(--letter-spacing-heading);
  text-transform: uppercase;
  margin-bottom: 0.85rem;
  color: var(--color-dark);
}

.feature-card p {
  font-size: 0.92rem;
  color: var(--color-muted);
  line-height: 1.7;
  margin: 0;
}

/* ============================================================
   Metrics Strip
   ============================================================ */
.metrics-strip {
  background: var(--color-surface);
  border-top: 1px solid var(--color-accent);
  border-bottom: 1px solid var(--color-accent);
  padding: 3.5rem 0;
}

.metrics-strip .container {
  display: flex;
  justify-content: center;
  align-items: flex-start;
  gap: 4rem;
  flex-wrap: wrap;
}

.metric {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 140px;
  padding: 0 1.5rem;
}

.metric + .metric {
  border-left: 1px solid var(--color-border-light);
}

.metric-label {
  font-family: var(--font-mono);
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: var(--letter-spacing-label);
  text-transform: uppercase;
  color: var(--color-muted);
  margin-bottom: 0.4rem;
}

.metric-value {
  font-family: var(--font-mono);
  font-size: 2.4rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  color: var(--color-dark);
  line-height: 1.2;
}

.metric-note {
  font-size: 0.75rem;
  color: var(--color-muted);
  margin-top: 0.3rem;
  letter-spacing: 0.03em;
}

/* ============================================================
   Testimonial
   ============================================================ */
.testimonial {
  padding: 5rem 0;
  background: #ecece6;
}

.testimonial blockquote {
  max-width: 700px;
  margin: 0 auto;
  border-left: 4px solid var(--color-accent);
  padding-left: 2rem;
}

.testimonial blockquote p {
  font-size: clamp(1.05rem, 2vw, 1.25rem);
  font-style: italic;
  line-height: 1.75;
  color: var(--color-dark);
  margin-bottom: 1.25rem;
}

.testimonial cite {
  display: block;
  font-style: normal;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--color-muted);
  letter-spacing: 0.03em;
}

/* ============================================================
   Footer
   ============================================================ */
.site-footer {
  background: var(--color-dark);
  color: rgba(255, 255, 255, 0.65);
  padding: 2.5rem 0;
}

.site-footer .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-tagline {
  margin: 0;
  font-size: 0.88rem;
  letter-spacing: 0.03em;
}

.social-links {
  display: flex;
  gap: 1.75rem;
}

.social-links a {
  color: rgba(255, 255, 255, 0.5);
  text-decoration: none;
  font-size: 0.88rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  transition: color 0.2s ease;
}

.social-links a:hover {
  color: var(--color-accent);
}

/* ============================================================
   Responsive — Tablet
   ============================================================ */
@media (max-width: 768px) {
  html {
    font-size: 15px;
  }

  .container {
    padding: 0 1.5rem;
  }

  .hero {
    padding: 5rem 0 3.5rem;
  }

  .features {
    padding: 3rem 0 4rem;
  }

  .features .container {
    grid-template-columns: 1fr;
    max-width: 440px;
    margin: 0 auto;
  }

  .metrics-strip .container {
    gap: 2rem;
  }

  .metric + .metric {
    border-left: none;
  }

  .metric {
    padding: 0 1rem;
  }

  .testimonial blockquote {
    border-left: none;
    padding-left: 0;
    text-align: center;
  }

  .site-footer .container {
    flex-direction: column;
    text-align: center;
  }
}

/* ============================================================
   Responsive — Small Mobile (320px+)
   ============================================================ */
@media (max-width: 480px) {
  html {
    font-size: 14px;
  }

  .container {
    padding: 0 1rem;
  }

  .hero {
    padding: 4rem 0 2.5rem;
  }

  .metrics-strip .container {
    flex-direction: column;
    align-items: center;
    gap: 2rem;
  }

  .metric + .metric {
    border-left: none;
    border-top: 1px solid var(--color-border-light);
    padding-top: 1.5rem;
  }

  .metric-value {
    font-size: 2rem;
  }

  .btn-primary {
    padding: 0.7rem 1.8rem;
    font-size: 0.9rem;
  }
}

