  letter-spacing: 0.04em;
}

/* ========== FOOTER ========== */
.site-footer {
  padding: 3rem 0 2rem;
  background-color: var(--bg);
}

.footer-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--border-light);
  margin-bottom: 1.5rem;
}

.footer-brand {
  display: flex;
  align-items: center;
