  transition: color 0.15s ease;
  display: flex;
  align-items: center;
}

.social-link:hover {
  color: var(--accent);
}

.social-link svg {
  width: 20px;
  height: 20px;
}

.footer-bottom {
  text-align: center;
  font-size: 0.8rem;
  color: var(--text-muted);
  letter-spacing: 0.03em;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.footer-bottom a {
  color: var(--accent);
