}

.footer-bottom a:hover {
  text-decoration: underline;
}

.footer-tagline {
  font-style: italic;
}

/* ========== RESPONSIVE ========== */
@media (max-width: 768px) {
  .hero-headline {
    font-size: 2rem;
  }

  .hero-subhead {
    font-size: 1rem;
