/* ==============================
   Murmur — Tech-Noir Stylesheet
   ============================== */

/* CSS Variables */
:root {
  --bg: #e4e4e0;
  --bg-alt: #f0f0ed;
  --text: #1a1a1a;
  --text-muted: #5a5a5a;
  --accent: #e8192a;
  --accent-hover: #c4101f;
  --border: #c0c0ba;
  --border-light: #d5d5d0;
  --card-bg: #fafaf8;
  --white: #ffffff;
  --font-body: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  --font-mono: 'SF Mono', 'Fira Code', 'Fira Mono', 'Roboto Mono', 'Cascadia Code', Consolas, monospace;
  --letter-spacing-heading: 0.06em;
  --max-width: 1100px;
  --radius: 2px;
}

/* Reset */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 100%;
}

body {
  font-family: var(--font-body);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Screen reader only */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ========== HEADER ========== */
.site-header {
  border-bottom: 1px solid var(--border);
  background-color: var(--bg);
  position: sticky;
  top: 0;
  z-index: 10;
}

.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 4rem;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  text-decoration: none;
  color: var(--text);
  font-weight: 700;
  letter-spacing: var(--letter-spacing-heading);
  text-transform: uppercase;
}

.logo-icon {
  font-size: 1.5rem;
  color: var(--accent);
}

.logo-text {
  font-size: 1.15rem;
}

.site-nav {
  display: flex;
  gap: 1.5rem;
}

.site-nav a {
  text-decoration: none;
  color: var(--text-muted);
  font-size: 0.9rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  transition: color 0.15s ease;
}

.site-nav a:hover {
  color: var(--accent);
}

/* ========== HERO ========== */
.hero {
  padding: 4rem 0 3rem;
  text-align: center;
}

.hero-badge {
  display: inline-block;
  padding: 0.3rem 0.8rem;
  border: 1px solid var(--border);
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 1.5rem;
  background-color: var(--bg-alt);
  color: var(--text-muted);
}

.hero-headline {
  font-size: 2.8rem;
  font-weight: 800;
  letter-spacing: var(--letter-spacing-heading);
  line-height: 1.15;
  margin-bottom: 1rem;
  color: var(--text);
}

.hero-headline em {
  font-style: italic;
  color: var(--accent);
}

.hero-subhead {
  font-size: 1.15rem;
  color: var(--text-muted);
  max-width: 640px;
  margin: 0 auto 2rem;
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  justify-content: center;
}

/* Buttons */
.btn {
  display: inline-block;
  padding: 0.8rem 1.6rem;
  font-size: 0.9rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  text-decoration: none;
  border: 1px solid var(--border);
  transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;
  cursor: pointer;
}

.btn-primary {
  background-color: var(--accent);
  color: var(--white);
  border-color: var(--accent);
}

.btn-primary:hover {
  background-color: var(--accent-hover);
  border-color: var(--accent-hover);
}

.btn-ghost {
  background-color: transparent;
  color: var(--text);
  border-color: var(--border);
}

.btn-ghost:hover {
  background-color: var(--bg-alt);
  border-color: var(--text-muted);
}

/* ========== METRICS STRIP ========== */
.metrics-strip {
  background-color: var(--bg-alt);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 3rem 0;
}

.metrics-title {
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
  text-align: center;
  margin-bottom: 2rem;
}

.metrics-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  text-align: center;
}

.metric-card {
  display: flex;
  flex-direction: column;
}

.metric-label {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 0.5rem;
}

.metric-value {
  font-family: var(--font-mono);
  font-size: 3rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--text);
  line-height: 1;
}

.metric-unit {
  font-size: 1.2rem;
  font-weight: 400;
  color: var(--text-muted);
}

.metric-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-top: 0.4rem;
}

/* ========== FEATURES ========== */
.features {
  padding: 4rem 0;
}

.section-heading {
  font-size: 1.4rem;
  font-weight: 700;
  letter-spacing: var(--letter-spacing-heading);
  text-align: center;
  margin-bottom: 3rem;
  color: var(--text);
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.feature-card {
  background-color: var(--card-bg);
  border: 1px solid var(--border-light);
  padding: 2rem 1.5rem;
  transition: border-color 0.2s ease;
}

.feature-card:hover {
  border-color: var(--accent);
}

.feature-icon {
  font-size: 2rem;
  margin-bottom: 1rem;
}

.feature-title {
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: var(--letter-spacing-heading);
  text-transform: uppercase;
  margin-bottom: 0.75rem;
  color: var(--text);
}

.feature-desc {
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.7;
}

/* ========== TESTIMONIAL ========== */
.testimonial {
  padding: 4rem 0;
  background-color: var(--bg-alt);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.testimonial-quote {
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote p {
  font-size: 1.2rem;
  font-style: italic;
  color: var(--text);
  line-height: 1.8;
  margin-bottom: 1.5rem;
  position: relative;
}

.testimonial-quote p::before {
  content: '“';
  font-size: 3rem;
  color: var(--accent);
  opacity: 0.4;
  position: absolute;
  left: -1.5rem;
  top: -0.5rem;
}

.testimonial-attribution {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.testimonial-attribution strong {
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--text);
}

.testimonial-attribution span {
  font-size: 0.8rem;
  color: var(--text-muted);
  letter-spacing: 0.04em;
}

/* ========== FOOTER ========== */
.site-footer {
  padding: 3rem 0 2rem;
  background-color: var(--bg);
}

.footer-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--border-light);
  margin-bottom: 1.5rem;
}

.footer-brand {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-weight: 700;
  letter-spacing: var(--letter-spacing-heading);
  text-transform: uppercase;
  color: var(--text-muted);
}

.footer-social {
  display: flex;
  gap: 1rem;
}

.social-link {
  color: var(--text-muted);
  transition: color 0.15s ease;
  display: flex;
  align-items: center;
}

.social-link:hover {
  color: var(--accent);
}

.social-link svg {
  width: 20px;
  height: 20px;
}

.footer-bottom {
  text-align: center;
  font-size: 0.8rem;
  color: var(--text-muted);
  letter-spacing: 0.03em;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.footer-bottom a {
  color: var(--accent);
  text-decoration: none;
}

.footer-bottom a:hover {
  text-decoration: underline;
}

.footer-tagline {
  font-style: italic;
}

/* ========== RESPONSIVE ========== */
@media (max-width: 768px) {
  .hero-headline {
    font-size: 2rem;
  }

  .hero-subhead {
    font-size: 1rem;
  }

  .metrics-grid,
  .features-grid {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  .metric-value {
    font-size: 2.5rem;
  }

  .features {
    padding: 3rem 0;
  }

  .section-heading {
    font-size: 1.2rem;
  }

  .site-nav {
    gap: 1rem;
  }

  .site-nav a {
    font-size: 0.8rem;
  }

  .footer-top {
    flex-direction: column;
    gap: 1.5rem;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 1rem;
  }

  .hero {
    padding: 3rem 0 2rem;
  }

  .hero-headline {
    font-size: 1.6rem;
  }

  .hero-badge {
    font-size: 0.7rem;
  }

  .hero-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .btn {
    text-align: center;
  }

  .testimonial-quote p {
    font-size: 1rem;
  }

  .testimonial-quote p::before {
    left: -0.8rem;
    font-size: 2rem;
    top: -0.3rem;
  }

  .metric-value {
    font-size: 2rem;
  }

  .site-header .container {
    flex-direction: column;
    height: auto;
    padding: 1rem;
    gap: 0.5rem;
  }

  .site-nav {
    gap: 1rem;
  }
}

