    background-color: var(--color-bg-inverse);
    color: var(--color-text-inverse);
    border-top: var(--border-subtle);
    border-bottom: var(--border-subtle);
}

#metrics .section__heading {
    color: rgba(245, 245, 242, 0.55);
}

.metrics__strip {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--space-xl) var(--space-2xl);
    margin-bottom: var(--space-lg);
}

.metric {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    min-width: 150px;
    flex: 0 1 auto;
}

.metric__label {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    letter-spacing: var(--letter-spacing-wide);
    color: rgba(245, 245, 242, 0.5);
    text-transform: uppercase;
    margin-bottom: 0.5rem;
    font-weight: 500;
}

.metric__label small {
    font-size: 0.62rem;
    letter-spacing: 0.04em;
    text-transform: none;
    color: rgba(245, 245, 242, 0.4);
    display: inline-block;
}

.metric__value {
    font-family: var(--font-mono);
    font-size: clamp(2.2rem, 5.5vw, 3.6rem);
    font-weight: 700;
    letter-spacing: 0;
    color: var(--color-text-inverse);
    line-height: 1;
    margin-bottom: 0.35rem;
}

.metric__unit {
    font-size: 0.45em;
    font-weight: 400;
    color: var(--color-accent);
}

.metric__desc {
    font-size: 0.7rem;
    color: rgba(245, 245, 242, 0.45);
    letter-spacing: 0.04em;
    font-family: var(--font-mono);
}

.metrics__footnote {
    text-align: center;
    font-family: var(--font-mono);
    font-size: 0.65rem;
    letter-spacing: 0.05em;
    color: rgba(245, 245, 242, 0.35);
}

/* ============================================================
   TESTIMONIAL
   ============================================================ */

.testimonial .container {
    max-width: var(--container-narrow);
}

.testimonial__quote {
    text-align: center;
}

.testimonial__quote blockquote {
    position: relative;
    margin-bottom: var(--space-lg);
}

.testimonial__quote blockquote p {
    font-family: var(--font-serif);
    font-size: clamp(1rem, 2vw, 1.25rem);
    font-style: italic;
    line-height: 1.7;
    color: var(--color-text);
    letter-spacing: 0.015em;
}

.testimonial__quote blockquote::before {
    content: "“";
    display: block;
    font-family: var(--font-serif);
    font-size: 4.5rem;
    line-height: 0.7;
    color: var(--color-accent);
    margin-bottom: 0.4rem;
    font-style: normal;
    font-weight: 700;
}

.testimonial__quote figcaption {
    display: flex;
    flex-direction: column;
    gap: 0.1rem;
    font-style: normal;
}

.testimonial__quote figcaption strong {
    font-family: var(--font-mono);
    font-size: 0.85rem;
    letter-spacing: var(--letter-spacing-wide);
    color: var(--color-text);
}

.testimonial__quote figcaption span {
    font-size: 0.75rem;
    color: var(--color-text-muted);
    letter-spacing: 0.03em;
}

/* ============================================================
   FOOTER
   ============================================================ */

.site-footer {
    border-top: var(--border-subtle);
    background-color: var(--color-bg-elevated);
    padding-block: var(--space-xl);
    margin-top: auto;
}

.footer__grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: var(--space-lg);
    align-items: start;
}

@media (min-width: 600px) {
    .footer__grid {
        grid-template-columns: 1fr auto auto;
        gap: var(--space-xl);
    }
}

.footer__wordmark {
    font-family: var(--font-mono);
    font-size: 0.9rem;
    font-weight: 700;
    letter-spacing: var(--letter-spacing-xwide);
    color: var(--color-text);
    margin-bottom: 0.25rem;
}

.footer__tagline {
    font-size: 0.75rem;
    color: var(--color-text-muted);
    letter-spacing: 0.03em;
}

.footer__social {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.footer__label {
    font-family: var(--font-mono);
    font-size: 0.65rem;
    letter-spacing: var(--letter-spacing-wide);
    text-transform: uppercase;
    color: var(--color-text-muted);
    margin-bottom: 0.25rem;
}

.footer__link {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    letter-spacing: 0.05em;
    color: var(--color-text-muted);
    padding-bottom: 1px;
    border-bottom: 1px solid transparent;
    width: fit-content;
    transition: color 0.2s ease, border-color 0.2s ease;
}

.footer__link:hover {
    color: var(--color-accent);
    border-bottom-color: var(--color-accent);
}

.footer__legal {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.footer__legal p {
    font-size: 0.7rem;
    color: var(--color-text-muted);
    letter-spacing: 0.03em;
}

/* ============================================================
   RESPONSIVE — Smallest screens (320px+)
   ============================================================ */

@media (max-width: 480px) {
    :root {
        --space-2xl: 2.5rem;
        --space-xl: 1.5rem;
        --space-lg: 1.25rem;
    }

    .nav {
        flex-wrap: wrap;
        gap: var(--space-sm);
        padding-block: var(--space-sm);
    }

    .nav__links {
        gap: var(--space-md);
        flex-wrap: wrap;
        justify-content: flex-start;
        width: 100%;
    }

    .nav__link {
        font-size: 0.68rem;
    }

    .hero {
        padding-top: var(--space-xl);
    }

    .hero__headline {
        font-size: 1.5rem;
        letter-spacing: 0.02em;
    }

    .hero__subhead {
        font-size: 0.88rem;
    }

    .hero__actions {
        flex-direction: column;
        align-items: stretch;
    }

    .btn {
        width: 100%;
        min-width: unset;
    }

    .features__grid {
        grid-template-columns: 1fr;
        gap: var(--space-md);
    }

    .feature-card {
        padding: var(--space-lg);
    }

    .metrics__strip {
        flex-direction: column;
        align-items: center;
        gap: var(--space-xl);
    }

    .metric {
        min-width: 100%;
    }

    .metric__value {
        font-size: 2.4rem;
    }

    .testimonial__quote blockquote p {
        font-size: 0.92rem;
    }

    .section__heading {
        margin-bottom: var(--space-lg);
        font-size: 0.65rem;
    }

    .footer__grid {
        grid-template-columns: 1fr;
        gap: var(--space-md);
        text-align: center;
    }

    .footer__social {
        align-items: center;
    }

    .footer__link {
        width: auto;
    }

    .footer__legal {
        align-items: center;
    }
}

/* ---------- Extra small (320px) ---------- */
@media (max-width: 360px) {
    .container {
        padding-inline: var(--space-sm);
    }

    .hero__headline {
        font-size: 1.35rem;
    }

    .metric__value {
        font-size: 2rem;
    }

    .nav__wordmark {
        font-size: 0.9rem;
    }
}

/* ---------- Wide screens (900px–1200px) ---------- */
@media (min-width: 900px) {
    .features__grid {
        gap: var(--space-xl);
    }

    .feature-card {
        padding: var(--space-xl) var(--space-xl);
    }

    .metrics__strip {
        gap: var(--space-2xl);
    }
}

/* ---------- Focus & accessibility ---------- */
:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
    border-radius: 2px;
}

/* Reduce motion for users who prefer it */
@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

/* Selection styling */
::selection {
    background-color: var(--color-accent);
    color: var(--color-text-inverse);
}

