    <meta name="description" content="Murmur is an open-source reliability harness that brings deterministic evaluation, pass@k aggregation, and drift monitoring to your coding agents.">
    <link rel="stylesheet" href="styles.css">
</head>
<body>

    <!-- ========== NAVIGATION ========== -->
    <header class="site-header">
        <nav class="nav container" aria-label="Main navigation">
