    <main>
        <!-- ========== HERO ========== -->
        <section class="hero section" aria-labelledby="hero-headline">
            <div class="container">
                <p class="hero__kicker">Open-source • Apache 2.0</p>
                <h1 id="hero-headline" class="hero__headline">
                    Give your agents a <em>murmur</em> of certainty before every deployment.
                </h1>
                <p class="hero__subhead">
                    Murmur is a thin, deterministic harness that plugs into any coding agent pipeline.
                    It benchmarks every commit, surfaces regressions, and tells you exactly how much
                    you can trust each generation — before it reaches production.
                </p>
                <div class="hero__actions">
                    <a href="#" class="btn btn--primary">Star on GitHub</a>
                    <a href="#" class="btn btn--secondary">Read the docs →</a>
                </div>
            </div>
        </section>

        <!-- ========== FEATURES ========== -->
        <section id="features" class="features section" aria-labelledby="features-heading">
            <div class="container">
                <h2 id="features-heading" class="section__heading">Three pillars of agent reliability</h2>
                <div class="features__grid">

                    <!-- Feature Card 1 -->
                    <article class="feature-card">
                        <div class="feature-card__icon" aria-hidden="true">◇</div>
                        <h3 class="feature-card__title">Deterministic Evaluation</h3>
                        <p class="feature-card__body">
                            Every Murmur run pins the random seed, temperature, and system prompt.
                            Two evaluations of the same commit always produce identical scores.
                            Stop chasing phantom regressions and start trusting your numbers.
                        </p>
                    </article>

                    <!-- Feature Card 2 -->
                    <article class="feature-card">
                        <div class="feature-card__icon" aria-hidden="true">◇</div>
                        <h3 class="feature-card__title">Pass<sup>k</sup> Aggregation</h3>
                        <p class="feature-card__body">
                            One sample is a gamble. Murmur runs your agent <em>k</em> times per task
                            and computes pass<sup>k</sup> — the probability that at least one sample
                            solves the problem. A sharper signal for a sharper model.
                        </p>
                    </article>

                    <!-- Feature Card 3 -->
                    <article class="feature-card">
                        <div class="feature-card__icon" aria-hidden="true">◇</div>
                        <h3 class="feature-card__title">Drift Monitoring</h3>
                        <p class="feature-card__body">
                            Model providers ship silent updates. Prompt templates rot. Murmur tracks
                            per-benchmark variance over time and alerts you the moment pass@1 drops
                            below your defined threshold. No surprises, just data.
                        </p>
                    </article>

                </div>
            </div>
        </section>

        <!-- ========== METRICS STRIP ========== -->
        <section id="metrics" class="metrics section" aria-labelledby="metrics-heading">
            <div class="container">
