                        <dt class="metric__label">pass<sup>k</sup> <small>(k=10)</small></dt>
                        <dd class="metric__value">99.2<span class="metric__unit">%</span></dd>
                        <dd class="metric__desc">at-least-one pass rate</dd>
                    </div>

                    <div class="metric">
                        <dt class="metric__label">variance</dt>
                        <dd class="metric__value">0.0031</dd>
                        <dd class="metric__desc">inter-run std deviation</dd>
                    </div>

