                <p class="metrics__footnote">Benchmarked on HumanEval-Full · 10 seeds · GPT-4o-2024-08-06</p>
            </div>
        </section>

        <!-- ========== TESTIMONIAL ========== -->
        <section class="testimonial section" aria-labelledby="testimonial-heading">
            <div class="container">
                <h2 id="testimonial-heading" class="section__heading">Trusted by teams shipping agentic code</h2>
                <figure class="testimonial__quote">
