                    <figcaption>
                        <strong>Dr. Elena Voss</strong>
                        <span>Staff Reliability Engineer, NexusDB</span>
                    </figcaption>
                </figure>
            </div>
        </section>
    </main>

    <!-- ========== FOOTER ========== -->
    <footer class="site-footer">
        <div class="container footer__grid">
            <div class="footer__brand">
                <p class="footer__wordmark">MURMUR</p>
                <p class="footer__tagline">Reliability harness for the agent era.</p>
