/* ============================================================
   MURMUR — Design System & Styles
   Tech-noir palette · CSS-only · Responsive 320px–1200px
   ============================================================ */

/* ----- CSS Custom Properties (Design Tokens) ----- */
:root {
    /* Palette */
    --color-bg:            #e4e4e0;
    --color-bg-elevated:   #ededeb;
    --color-bg-inverse:    #1a1a1a;
    --color-surface:       #f5f5f2;

    --color-text:          #1a1a1a;
    --color-text-muted:    #5c5c57;
    --color-text-inverse:  #f5f5f2;

    --color-accent:        #e8192a;
    --color-accent-hover:  #c41523;
    --color-accent-subtle: rgba(232, 25, 42, 0.06);

    --color-border:        #c5c5c0;
    --color-border-light:  #d6d6d2;
    --color-border-subtle: #dededa;

    /* Typography */
    --font-sans:  "Inter", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    --font-mono:  "SF Mono", "Fira Code", "Cascadia Code", "JetBrains Mono", "IBM Plex Mono", "Consolas", monospace;
    --font-serif: "Georgia", "Times New Roman", serif;

    --letter-spacing-heading: 0.04em;
    --letter-spacing-wide:    0.08em;
    --letter-spacing-xwide:   0.14em;

    /* Spacing */
    --space-xs:   0.375rem;
    --space-sm:   0.75rem;
    --space-md:   1.25rem;
    --space-lg:   2rem;
    --space-xl:   3rem;
    --space-2xl:  4.5rem;

    /* Layout */
    --container-max: 1100px;
    --container-narrow: 780px;
    --radius: 4px;
    --radius-lg: 8px;

    /* Borders */
    --border-thin: 1px solid var(--color-border);
    --border-subtle: 1px solid var(--color-border-subtle);
    --border-light: 1px solid var(--color-border-light);
}

/* ----- Reset & Base ----- */
*,
*::before,
*::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    font-size: 16px;
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
}

body {
    font-family: var(--font-sans);
    background-color: var(--color-bg);
    color: var(--color-text);
    line-height: 1.6;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

main {
    flex: 1;
}

img,
svg {
    display: block;
    max-width: 100%;
    height: auto;
}

a {
    color: inherit;
    text-decoration: none;
    transition: color 0.2s ease, border-color 0.2s ease, background-color 0.2s ease;
}

ul {
    list-style: none;
}

em {
    font-style: italic;
    color: var(--color-accent);
}

/* ----- Utility: Container ----- */
.container {
    width: 100%;
    max-width: var(--container-max);
    margin-inline: auto;
    padding-inline: var(--space-md);
}

.section {
    padding-block: var(--space-2xl);
}

/* ----- Section Heading ----- */
.section__heading {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    font-weight: 600;
    letter-spacing: var(--letter-spacing-xwide);
    text-transform: uppercase;
    color: var(--color-text-muted);
    text-align: center;
    margin-bottom: var(--space-xl);
}

/* ============================================================
   HEADER / NAVIGATION
   ============================================================ */

.site-header {
    border-bottom: var(--border-subtle);
    background-color: var(--color-bg);
    position: sticky;
    top: 0;
    z-index: 100;
}

.nav {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-block: var(--space-sm);
    min-height: 56px;
}

.nav__logo {
    display: flex;
    align-items: baseline;
    gap: var(--space-xs);
    text-decoration: none;
}

.nav__wordmark {
    font-family: var(--font-mono);
    font-size: 1.05rem;
    font-weight: 700;
    letter-spacing: var(--letter-spacing-xwide);
    color: var(--color-text);
    transition: color 0.2s ease;
}

.nav__logo:hover .nav__wordmark {
    color: var(--color-accent);
}

.nav__version {
    font-family: var(--font-mono);
    font-size: 0.68rem;
    color: var(--color-text-muted);
    letter-spacing: var(--letter-spacing-wide);
}

.nav__links {
    display: flex;
    align-items: center;
    gap: var(--space-lg);
}

.nav__link {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    letter-spacing: var(--letter-spacing-wide);
    color: var(--color-text-muted);
    text-transform: uppercase;
    padding-block: 0.3rem;
    border-bottom: 1px solid transparent;
    transition: color 0.2s ease, border-color 0.2s ease;
}

.nav__link:hover {
    color: var(--color-text);
    border-bottom-color: var(--color-accent);
}

.nav__link--github {
    border: var(--border-subtle);
    border-radius: var(--radius);
    padding: 0.35rem 0.85rem;
    font-size: 0.7rem;
}

.nav__link--github:hover {
    border-color: var(--color-accent);
    color: var(--color-accent);
    background-color: var(--color-accent-subtle);
}

/* ============================================================
   HERO
   ============================================================ */

.hero {
    text-align: center;
    padding-top: var(--space-2xl);
    padding-bottom: var(--space-2xl);
}

.hero__kicker {
    display: inline-block;
    font-family: var(--font-mono);
    font-size: 0.72rem;
    letter-spacing: var(--letter-spacing-wide);
    color: var(--color-text-muted);
    text-transform: uppercase;
    border: var(--border-subtle);
    border-radius: 999px;
    padding: 0.3rem 1rem;
    margin-bottom: var(--space-lg);
    background-color: var(--color-bg-elevated);
}

.hero__headline {
    font-size: clamp(1.75rem, 5vw, 3.4rem);
    font-weight: 750;
    letter-spacing: var(--letter-spacing-heading);
    line-height: 1.15;
    max-width: 820px;
    margin-inline: auto;
    margin-bottom: var(--space-md);
    color: var(--color-text);
}

.hero__headline em {
    font-style: normal;
    text-decoration: underline;
    text-decoration-color: var(--color-accent);
    text-underline-offset: 0.18em;
    text-decoration-thickness: 2px;
}

.hero__subhead {
    font-size: clamp(0.95rem, 1.8vw, 1.15rem);
    color: var(--color-text-muted);
    max-width: 620px;
    margin-inline: auto;
    margin-bottom: var(--space-xl);
    line-height: 1.7;
    letter-spacing: 0.01em;
}

.hero__actions {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-sm);
    justify-content: center;
    align-items: center;
}

/* ----- Buttons ----- */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-family: var(--font-mono);
    font-size: 0.82rem;
    font-weight: 600;
    letter-spacing: var(--letter-spacing-wide);
    padding: 0.75rem 1.75rem;
    border-radius: var(--radius);
    cursor: pointer;
    transition: all 0.2s ease;
    border: 1px solid transparent;
    min-width: 160px;
    text-align: center;
}

.btn--primary {
    background-color: var(--color-accent);
    color: var(--color-text-inverse);
    border-color: var(--color-accent);
}

.btn--primary:hover {
    background-color: var(--color-accent-hover);
    border-color: var(--color-accent-hover);
}

.btn--secondary {
    background-color: transparent;
    color: var(--color-text);
    border-color: var(--color-border);
}

.btn--secondary:hover {
    border-color: var(--color-text);
    background-color: var(--color-bg-elevated);
}

/* ============================================================
   FEATURES
   ============================================================ */

.features__grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: var(--space-lg);
}

@media (min-width: 620px) {
    .features__grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (min-width: 920px) {
    .features__grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

.feature-card {
    background-color: var(--color-bg-elevated);
    border: var(--border-subtle);
    border-radius: var(--radius-lg);
    padding: var(--space-xl) var(--space-lg);
    position: relative;
    transition: border-color 0.25s ease, box-shadow 0.25s ease, transform 0.2s ease;
}

.feature-card:hover {
    border-color: var(--color-accent);
    box-shadow: 0 0 0 1px var(--color-accent), 0 4px 20px rgba(0, 0, 0, 0.06);
    transform: translateY(-2px);
}

.feature-card__icon {
    font-size: 1.4rem;
    color: var(--color-accent);
    margin-bottom: var(--space-md);
    line-height: 1;
    letter-spacing: 0;
}

.feature-card__title {
    font-size: 1.05rem;
    font-weight: 700;
    letter-spacing: var(--letter-spacing-heading);
    margin-bottom: var(--space-sm);
    color: var(--color-text);
}

.feature-card__body {
    font-size: 0.88rem;
    color: var(--color-text-muted);
    line-height: 1.65;
    letter-spacing: 0.015em;
}

.feature-card__body em {
    font-style: normal;
    font-family: var(--font-mono);
    font-size: 0.92em;
    color: var(--color-accent);
}

/* ============================================================
   METRICS STRIP
   ============================================================ */

#metrics.metrics {
    background-color: var(--color-bg-inverse);
    color: var(--color-text-inverse);
    border-top: var(--border-subtle);
    border-bottom: var(--border-subtle);
}

#metrics .section__heading {
    color: rgba(245, 245, 242, 0.55);
}

.metrics__strip {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--space-xl) var(--space-2xl);
    margin-bottom: var(--space-lg);
}

.metric {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    min-width: 150px;
    flex: 0 1 auto;
}

.metric__label {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    letter-spacing: var(--letter-spacing-wide);
    color: rgba(245, 245, 242, 0.5);
    text-transform: uppercase;
    margin-bottom: 0.5rem;
    font-weight: 500;
}

.metric__label small {
    font-size: 0.62rem;
    letter-spacing: 0.04em;
    text-transform: none;
    color: rgba(245, 245, 242, 0.4);
    display: inline-block;
}

.metric__value {
    font-family: var(--font-mono);
    font-size: clamp(2.2rem, 5.5vw, 3.6rem);
    font-weight: 700;
    letter-spacing: 0;
    color: var(--color-text-inverse);
    line-height: 1;
    margin-bottom: 0.35rem;
}

.metric__unit {
    font-size: 0.45em;
    font-weight: 400;
    color: var(--color-accent);
}

.metric__desc {
    font-size: 0.7rem;
    color: rgba(245, 245, 242, 0.45);
    letter-spacing: 0.04em;
    font-family: var(--font-mono);
}

.metrics__footnote {
    text-align: center;
    font-family: var(--font-mono);
    font-size: 0.65rem;
    letter-spacing: 0.05em;
    color: rgba(245, 245, 242, 0.35);
}

/* ============================================================
   TESTIMONIAL
   ============================================================ */

.testimonial .container {
    max-width: var(--container-narrow);
}

.testimonial__quote {
    text-align: center;
}

.testimonial__quote blockquote {
    position: relative;
    margin-bottom: var(--space-lg);
}

.testimonial__quote blockquote p {
    font-family: var(--font-serif);
    font-size: clamp(1rem, 2vw, 1.25rem);
    font-style: italic;
    line-height: 1.7;
    color: var(--color-text);
    letter-spacing: 0.015em;
}

.testimonial__quote blockquote::before {
    content: "“";
    display: block;
    font-family: var(--font-serif);
    font-size: 4.5rem;
    line-height: 0.7;
    color: var(--color-accent);
    margin-bottom: 0.4rem;
    font-style: normal;
    font-weight: 700;
}

.testimonial__quote figcaption {
    display: flex;
    flex-direction: column;
    gap: 0.1rem;
    font-style: normal;
}

.testimonial__quote figcaption strong {
    font-family: var(--font-mono);
    font-size: 0.85rem;
    letter-spacing: var(--letter-spacing-wide);
    color: var(--color-text);
}

.testimonial__quote figcaption span {
    font-size: 0.75rem;
    color: var(--color-text-muted);
    letter-spacing: 0.03em;
}

/* ============================================================
   FOOTER
   ============================================================ */

.site-footer {
    border-top: var(--border-subtle);
    background-color: var(--color-bg-elevated);
    padding-block: var(--space-xl);
    margin-top: auto;
}

.footer__grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: var(--space-lg);
    align-items: start;
}

@media (min-width: 600px) {
    .footer__grid {
        grid-template-columns: 1fr auto auto;
        gap: var(--space-xl);
    }
}

.footer__wordmark {
    font-family: var(--font-mono);
    font-size: 0.9rem;
    font-weight: 700;
    letter-spacing: var(--letter-spacing-xwide);
    color: var(--color-text);
    margin-bottom: 0.25rem;
}

.footer__tagline {
    font-size: 0.75rem;
    color: var(--color-text-muted);
    letter-spacing: 0.03em;
}

.footer__social {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.footer__label {
    font-family: var(--font-mono);
    font-size: 0.65rem;
    letter-spacing: var(--letter-spacing-wide);
    text-transform: uppercase;
    color: var(--color-text-muted);
    margin-bottom: 0.25rem;
}

.footer__link {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    letter-spacing: 0.05em;
    color: var(--color-text-muted);
    padding-bottom: 1px;
    border-bottom: 1px solid transparent;
    width: fit-content;
    transition: color 0.2s ease, border-color 0.2s ease;
}

.footer__link:hover {
    color: var(--color-accent);
    border-bottom-color: var(--color-accent);
}

.footer__legal {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.footer__legal p {
    font-size: 0.7rem;
    color: var(--color-text-muted);
    letter-spacing: 0.03em;
}

/* ============================================================
   RESPONSIVE — Smallest screens (320px+)
   ============================================================ */

@media (max-width: 480px) {
    :root {
        --space-2xl: 2.5rem;
        --space-xl: 1.5rem;
        --space-lg: 1.25rem;
    }

    .nav {
        flex-wrap: wrap;
        gap: var(--space-sm);
        padding-block: var(--space-sm);
    }

    .nav__links {
        gap: var(--space-md);
        flex-wrap: wrap;
        justify-content: flex-start;
        width: 100%;
    }

    .nav__link {
        font-size: 0.68rem;
    }

    .hero {
        padding-top: var(--space-xl);
    }

    .hero__headline {
        font-size: 1.5rem;
        letter-spacing: 0.02em;
    }

    .hero__subhead {
        font-size: 0.88rem;
    }

    .hero__actions {
        flex-direction: column;
        align-items: stretch;
    }

    .btn {
        width: 100%;
        min-width: unset;
    }

    .features__grid {
        grid-template-columns: 1fr;
        gap: var(--space-md);
    }

    .feature-card {
        padding: var(--space-lg);
    }

    .metrics__strip {
        flex-direction: column;
        align-items: center;
        gap: var(--space-xl);
    }

    .metric {
        min-width: 100%;
    }

    .metric__value {
        font-size: 2.4rem;
    }

    .testimonial__quote blockquote p {
        font-size: 0.92rem;
    }

    .section__heading {
        margin-bottom: var(--space-lg);
        font-size: 0.65rem;
    }

    .footer__grid {
        grid-template-columns: 1fr;
        gap: var(--space-md);
        text-align: center;
    }

    .footer__social {
        align-items: center;
    }

    .footer__link {
        width: auto;
    }

    .footer__legal {
        align-items: center;
    }
}

/* ---------- Extra small (320px) ---------- */
@media (max-width: 360px) {
    .container {
        padding-inline: var(--space-sm);
    }

    .hero__headline {
        font-size: 1.35rem;
    }

    .metric__value {
        font-size: 2rem;
    }

    .nav__wordmark {
        font-size: 0.9rem;
    }
}

/* ---------- Wide screens (900px–1200px) ---------- */
@media (min-width: 900px) {
    .features__grid {
        gap: var(--space-xl);
    }

    .feature-card {
        padding: var(--space-xl) var(--space-xl);
    }

    .metrics__strip {
        gap: var(--space-2xl);
    }
}

/* ---------- Focus & accessibility ---------- */
:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
    border-radius: 2px;
}

/* Reduce motion for users who prefer it */
@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

/* Selection styling */
::selection {
    background-color: var(--color-accent);
    color: var(--color-text-inverse);
}

args.content:
:root {
  --bg: #e4e4e0;
  --accent: #e8192a;
  --text-main: #1a1a1a;
  --text-muted: #555;
  --border: #c0c0c0;
  --card-bg: #f0f0eb;
  --heading-letter-spacing: 0.12em;
  --border-width: 1px;
  --max-width: 1200px;
  --pad: 1.5rem;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 100%;
  background: var(--bg);
  color: var(--text-main);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.6;
}

body {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ---------- Typography ---------- */
h1, h2, h3 {
  font-weight: 600;
  letter-spacing: var(--heading-letter-spacing);
  text-transform: uppercase;
  line-height: 1.2;
}

h1 { font-size: clamp(1.8rem, 5vw, 3rem); }
h2 { font-size: clamp(1.4rem, 4vw, 2rem); }
h3 { font-size: 1.1rem; }

a {
  color: var(--accent);
  text-decoration: none;
  transition: color 0.2s;
}
a:hover { color: #b5121f; }

/* ---------- Header ---------- */
.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: var(--border-width) solid var(--border);
  padding: 1rem var(--pad);
  max-width: var(--max-width);
  margin: 0 auto;
  width: 100%;
}

.logo {
  font-family: ui-monospace, 'Cascadia Code', 'Source Code Pro', Menlo, Consolas, monospace;
  font-size: 1.4rem;
  letter-spacing: 0.08em;
  text-transform: lowercase;
}

.header-nav {
  display: flex;
  gap: 1.5rem;
}
.header-nav a {
  font-weight: 500;
  color: var(--text-main);
  text-transform: uppercase;
  font-size: 0.85rem;
  letter-spacing: 0.06em;
  border-bottom: 2px solid transparent;
  padding-bottom: 2px;
}
.header-nav a:hover {
  border-bottom-color: var(--accent);
  color: var(--accent);
}

/* ---------- Hero ---------- */
.hero {
  text-align: center;
  padding: clamp(3rem, 8vw, 5rem) var(--pad);
  max-width: 800px;
  margin: 0 auto;
  border-bottom: var(--border-width) solid var(--border);
}

.hero h1 {
  margin-bottom: 1rem;
}

.hero-subhead {
  font-size: 1.1rem;
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto 2rem;
  line-height: 1.7;
}

.cta {
  display: inline-block;
  background: var(--accent);
  color: #fff;
  padding: 0.8rem 2rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  border: none;
  border-radius: 4px;
  transition: background 0.2s;
}
.cta:hover {
  background: #b5121f;
  color: #fff;
}

/* ---------- Metrics Strip ---------- */
#metrics {
  display: flex;
  justify-content: center;
  gap: clamp(1rem, 4vw, 3rem);
  padding: 2rem var(--pad);
  border-bottom: var(--border-width) solid var(--border);
  flex-wrap: wrap;
}

.metric {
  text-align: center;
  flex: 1 1 120px;
  max-width: 180px;
}

.metric-value {
  display: block;
  font-family: ui-monospace, 'Cascadia Code', 'Source Code Pro', Menlo, Consolas, monospace;
  font-size: 2.4rem;
  font-weight: 600;
  color: var(--accent);
  line-height: 1;
}

.metric-label {
  display: block;
  margin-top: 0.3rem;
  font-family: ui-monospace, 'Cascadia Code', 'Source Code Pro', Menlo, Consolas, monospace;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
}

/* ---------- Features Section ---------- */
.features {
  padding: 3rem var(--pad);
  border-bottom: var(--border-width) solid var(--border);
}

.section-title {
  text-align: center;
  margin-bottom: 2.5rem;
}

.feature-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 2rem;
  max-width: var(--max-width);
  margin: 0 auto;
}

.feature-card {
  background: var(--card-bg);
  border: var(--border-width) solid var(--border);
  padding: 1.8rem;
  border-radius: 4px;
  transition: border-color 0.2s;
}
.feature-card:hover {
  border-color: var(--accent);
}

.feature-card h3 {
  color: var(--accent);
  margin-bottom: 0.8rem;
}

.feature-card p {
  color: var(--text-muted);
  line-height: 1.7;
}

/* ---------- Testimonial ---------- */
.testimonial {
  padding: 3rem var(--pad);
  border-bottom: var(--border-width) solid var(--border);
  display: flex;
  justify-content: center;
}

.testimonial blockquote {
  max-width: 650px;
  text-align: center;
  font-style: italic;
  font-size: 1.2rem;
  line-height: 1.7;
  color: var(--text-main);
  border-left: 3px solid var(--accent);
  padding-left: 1.5rem;
}

.testimonial cite {
  display: block;
  margin-top: 1rem;
  font-style: normal;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-size: 0.9rem;
  color: var(--text-muted);
}

/* ---------- Footer ---------- */
.site-footer {
  margin-top: auto;
  padding: 2rem var(--pad);
  border-top: var(--border-width) solid var(--border);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
  text-align: center;
}

.footer-logo {
  font-family: ui-monospace, 'Cascadia Code', 'Source Code Pro', Menlo, Consolas, monospace;
  font-size: 1.2rem;
  text-transform: lowercase;
  color: var(--text-main);
}

.social-placeholders {
  display: flex;
  gap: 1.8rem;
  margin: 0.5rem 0;
}

.social-placeholders a {
  color: var(--text-muted);
  font-size: 0.9rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  border-bottom: 1px solid transparent;
  padding-bottom: 2px;
  transition: color 0.2s, border-color 0.2s;
}
.social-placeholders a:hover {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.footer-note {
  font-size: 0.8rem;
  color: var(--text-muted);
  letter-spacing: 0.05em;
}

/* ---------- Responsive Tweaks ---------- */
@media (max-width: 600px) {
  .site-header {
    flex-direction: column;
    gap: 0.8rem;
  }
  .header-nav {
    flex-wrap: wrap;
    justify-content: center;
    gap: 1rem;
  }
  .feature-cards {
    grid-template-columns: 1fr;
  }
  .testimonial blockquote {
    padding-left: 1rem;
    font-size: 1rem;
  }
}

