    <!-- Hero -->
    <section class="hero">
      <h1>murmur gives you a reason to trust your coding agents</h1>
      <p class="hero-subhead">
        Open‑source harness for benchmarking, continuous reliability monitoring,
        and catching regressions before they reach production.
      </p>
      <a href="#" class="cta">Get Started</a>
    </section>

