    <div id="metrics" class="metrics-strip">
      <div class="metric">
        <span class="metric-value">84.7%</span>
        <span class="metric-label">Pass@1</span>
      </div>
      <div class="metric">
        <span class="metric-value">92.3%</span>
        <span class="metric-label">Pass^k</span>
      </div>
      <div class="metric">
        <span class="metric-value">0.0032</span>
        <span class="metric-label">Variance</span>
      </div>
    </div>

    <!-- Feature cards -->
    <section class="features">
      <h2 class="section-title">Why Teams Rely on Murmur</h2>
      <div class="feature-cards">
        <article class="feature-card">
          <h3>Benchmark Any Agent</h3>
          <p>
            Run thousands of tasks across models, settings, and tool chains.
            Murmur tracks first‑shot accuracy, consensus quality, and response
            stability so you always know where your agent stands.
          </p>
        </article>
        <article class="feature-card">
          <h3>Catch Regressions Early</h3>
          <p>
            Every commit triggers a fast sweep. If a prompt change drops your
            pass@1 by a single point you get an alert, not a mystery outage.
            Continuous reliability baked into CI.
          </p>
        </article>
        <article class="feature-card">
          <h3>Open &amp; Composable</h3>
          <p>
            No lock‑in. Works with any framework, any model. Murmur is a
            standalone binary you can drop into your pipeline and customize
            like any Rust crate. MIT licensed.
          </p>
        </article>
      </div>
    </section>

    <!-- Testimonial -->
    <section class="testimonial">
      <blockquote>
        <p>
