    <!-- FEATURES -->
    <section id="features" class="features" aria-labelledby="features-heading">
      <div class="container">
        <h2 id="features-heading" class="section-heading">Agent Reliability, Measured</h2>
        <p class="section-subhead">Three signals that tell you whether your coding agents are ready for production.</p>
        <div class="features-grid">
