/* =============================================
   MURMUR – Tech‑Noir Palette & Global Reset
   ============================================= */
:root {
  --color-bg:          #e4e4e0;
  --color-surface:     #f4f4f0;
  --color-text:        #2d2d2b;
  --color-text-muted:  #63635f;
  --color-accent:      #e8192a;
  --color-accent-hover:#c71220;
  --color-border:      #c4c4c0;
  --color-border-light:#d9d9d5;

  --font-mono:         'SF Mono', 'Cascadia Code', 'Roboto Mono', Menlo, monospace;

  --letter-spacing-h1: 5px;
  --letter-spacing-h2: 2.5px;

  --radius:            4px;
  --transition:        0.2s ease;
}

*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-width: 320px;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

/* =============================================
   UTILITY CLASSES
   ============================================= */
.container {
  width: 100%;
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 24px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* =============================================
   HEADER
   ============================================= */
.site-header {
  border-bottom: 1px solid var(--color-border-light);
  background: var(--color-bg);
}

.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  font-size: 1.25rem;
  letter-spacing: 1px;
  color: var(--color-text);
}

.logo-mark {
  color: var(--color-accent);
  font-size: 1.5rem;
  line-height: 1;
}

.site-nav {
  display: flex;
  align-items: center;
  gap: 28px;
}

.site-nav a {
  font-size: 0.9rem;
  font-weight: 500;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: var(--color-text-muted);
  border-bottom: 2px solid transparent;
  padding-bottom: 4px;
  transition: color var(--transition), border-color var(--transition);
}

.site-nav a:hover,
.site-nav a:focus-visible {
  color: var(--color-text);
  border-bottom-color: var(--color-accent);
}

.nav-cta {
  color: var(--color-accent) !important;
  font-weight: 600;
}

/* =============================================
   HERO
   ============================================= */
.hero {
  padding: 96px 0 80px;
  text-align: center;
  border-bottom: 1px solid var(--color-border-light);
}

.hero-eyebrow {
  font-family: var(--font-mono);
  font-size: 0.8rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 16px;
}

.hero-headline {
  font-size: clamp(2.2rem, 6vw, 3.8rem);
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: var(--letter-spacing-h1);
  margin-bottom: 24px;
  color: var(--color-text);
}

.hero-headline br {
  display: block;
}

.hero-subhead {
  max-width: 640px;
  margin: 0 auto 40px;
  font-size: 1.1rem;
  color: var(--color-text-muted);
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 16px;
}

/* =============================================
   BUTTONS
   ============================================= */
.btn {
  display: inline-block;
  padding: 12px 28px;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.5px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  cursor: pointer;
  transition: all var(--transition);
  background: transparent;
  color: var(--color-text);
  text-transform: uppercase;
}

.btn-primary {
  background: var(--color-accent);
  color: #fff;
  border-color: var(--color-accent);
}

.btn-primary:hover {
  background: var(--color-accent-hover);
  border-color: var(--color-accent-hover);
}

.btn-ghost {
  background: transparent;
  border-color: var(--color-border);
}

.btn-ghost:hover {
  background: var(--color-surface);
  border-color: var(--color-text-muted);
}

/* =============================================
   METRICS STRIP
   ============================================= */
.metrics-strip {
  border-bottom: 1px solid var(--color-border-light);
  padding: 64px 0;
  background: var(--color-surface);
}

.metrics-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.metric {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.metric-label {
  font-family: var(--font-mono);
  font-size: 0.85rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  margin-bottom: 8px;
}

.metric-value {
  font-family: var(--font-mono);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-text);
  letter-spacing: 0.05em;
  margin-bottom: 8px;
}

.metric-value sup {
  font-size: 0.6em;
  vertical-align: super;
  line-height: 0;
}

.metric-desc {
  font-size: 0.9rem;
  color: var(--color-text-muted);
  line-height: 1.5;
  max-width: 240px;
}

/* =============================================
   FEATURES
   ============================================= */
.features {
  padding: 96px 0 80px;
  border-bottom: 1px solid var(--color-border-light);
}

.section-heading {
  font-size: clamp(1.8rem, 4vw, 2.4rem);
  font-weight: 700;
  letter-spacing: var(--letter-spacing-h2);
  text-align: center;
  margin-bottom: 16px;
  color: var(--color-text);
}

.section-subhead {
  font-size: 1.05rem;
  color: var(--color-text-muted);
  text-align: center;
  max-width: 560px;
  margin: 0 auto 64px;
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 40px;
}

.feature-card {
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 40px 32px;
  background: var(--color-surface);
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.feature-card:hover {
  border-color: var(--color-accent);
  box-shadow: 0 4px 16px rgba(0,0,0,0.05);
}

.feature-number {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.15em;
  color: var(--color-accent);
  margin-bottom: 20px;
}

.feature-title {
  font-size: 1.3rem;
  font-weight: 700;
  letter-spacing: 1px;
  margin-bottom: 16px;
  color: var(--color-text);
}

.feature-title sup {
  font-size: 0.6em;
}

.feature-desc {
  font-size: 0.95rem;
  color: var(--color-text-muted);
  line-height: 1.7;
  flex: 1;
}

/* =============================================
   TESTIMONIAL
   ============================================= */
.testimonial {
  padding: 80px 0 96px;
  border-bottom: 1px solid var(--color-border-light);
}

.testimonial-figure {
  max-width: 680px;
  margin: 0 auto;
  text-align: left;
}

.testimonial-quote {
  font-size: 1.2rem;
  font-style: italic;
  line-height: 1.7;
  color: var(--color-text);
  margin-bottom: 24px;
  position: relative;
  padding-left: 32px;
}

.quote-mark {
  position: absolute;
  left: 0;
  top: 0;
  font-size: 2.5rem;
  color: var(--color-accent);
  line-height: 1;
  font-style: normal;
  opacity: 0.9;
}

.testimonial-attribution {
  display: flex;
  flex-direction: column;
  font-size: 0.95rem;
}

.testimonial-attribution strong {
  font-weight: 700;
  color: var(--color-text);
}

.testimonial-attribution span {
  color: var(--color-text-muted);
  font-size: 0.9rem;
  margin-top: 4px;
}

/* =============================================
   FOOTER
   ============================================= */
.site-footer {
  background: var(--color-surface);
  border-top: 1px solid var(--color-border-light);
  padding: 64px 0 40px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand .logo-text {
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: 1px;
  display: block;
  margin-bottom: 12px;
}

.footer-tagline {
  font-size: 0.9rem;
  color: var(--color-text-muted);
  max-width: 280px;
}

.footer-heading {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--color-text-muted);
  margin-bottom: 16px;
}

.footer-links a {
  display: block;
  font-size: 0.95rem;
  color: var(--color-text);
  margin-bottom: 10px;
  transition: color var(--transition);
}

.footer-links a:hover {
  color: var(--color-accent);
}

.footer-bottom {
  border-top: 1px solid var(--color-border-light);
  padding-top: 24px;
  text-align: center;
}

.footer-bottom p {
  font-size: 0.85rem;
  color: var(--color-text-muted);
}

/* =============================================
   RESPONSIVE
   ============================================= */
@media (max-width: 900px) {
  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .site-header .container {
    height: auto;
    flex-direction: column;
    padding: 16px 24px;
    gap: 12px;
  }

  .site-nav {
    gap: 20px;
  }

  .hero {
    padding: 64px 0 56px;
  }

  .metrics-grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .features-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: 40px;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 20px;
  }

  .site-nav {
    gap: 16px;
    flex-wrap: wrap;
    justify-content: center;
  }

  .hero-headline {
    letter-spacing: 3px;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 32px;
    text-align: center;
  }

  .footer-tagline {
    max-width: 100%;
  }

  .testimonial-quote {
    font-size: 1.05rem;
    padding-left: 28px;
  }
}
